const sb=window.__simantabSb,$=id=>document.getElementById(id),profile=()=>window.__simantabProfile||{};
if(!sb)return;

const Q=[[1,"KEPRIBADIAN","Dalam rapat evaluasi pembagian tugas, seorang guru senior mempersoalkan beban kerja yang Anda tetapkan. Ia membawa data jam mengajar yang menunjukkan ketimpangan, tetapi data itu belum memasukkan dua tugas tambahan yang baru ditetapkan. Rapat harus menghasilkan keputusan maksimal dua hari lagi karena jadwal akan segera berlaku. Guru lain mulai terbelah antara yang mendukung dan menolak. Pendekatan penanganan yang paling tepat adalah:",["Memberlakukan pembagian awal selama satu pekan dan memeriksa data tambahan setelah jadwal berjalan agar layanan tidak tertunda.","Menahan finalisasi bagian yang dipersoalkan dan memverifikasi seluruh beban dalam dua hari dengan kriteria yang terbuka.","Membahas ulang semua pembagian saat rapat berlangsung dan meminta guru menyepakati perubahan berdasarkan data yang mereka bawa.","Meminta guru senior menyusun pembagian pengganti untuk meredakan perpecahan di antara guru."]],[2,"KEPRIBADIAN","Seorang guru yang merupakan sahabat dekat Anda tercatat terlambat enam kali dalam satu bulan. Ia menjelaskan sedang merawat orang tua yang sakit dan selama ini kinerjanya baik. Guru lain mulai mempertanyakan konsistensi aturan disiplin sekolah. Respons kepala sekolah yang paling tepat adalah:",["Memberikan kelonggaran satu bulan karena kinerjanya baik dan baru meninjau pengaruh keterlambatan setelah masa toleransi berakhir.","Menyerahkan seluruh penanganan kepada koordinator agar hubungan persahabatan tidak memengaruhi kepala sekolah dalam mengambil keputusan disiplin.","Mengklarifikasi kebutuhan keluarga, menerapkan standar yang sama, dan menyepakati dukungan dengan batas serta pemantauan.","Memberikan teguran lebih dahulu untuk menunjukkan konsistensi aturan dan membahas kebutuhan dukungan setelah keterlambatan berikutnya terjadi."]],[3,"KEPRIBADIAN","Program literasi unggulan yang Anda gagas telah berjalan satu semester, mendapat publikasi positif, dan disukai sebagian besar guru. Namun asesmen menunjukkan kebiasaan membaca siswa nyaris tidak berubah. Data observasi juga memperlihatkan siswa sering menjalankan kegiatan sekadar memenuhi kewajiban. Tim pelaksana merasa program belum diberi waktu cukup dan khawatir penghentian akan menurunkan motivasi. Respons kepala sekolah yang paling tepat adalah:",["Melanjutkan program satu semester dengan pelaksanaan yang lebih konsisten karena waktu pembentukan kebiasaan belum dianggap cukup oleh tim.","Mengurangi kegiatan yang paling membebani guru dan mempertahankan komponen lainnya agar motivasi pelaksana serta publikasi positif tetap terjaga.","Melakukan asesmen lagi pada akhir semester berikutnya dengan rancangan program tetap agar perubahan hasil dapat dibandingkan antarsemester secara langsung.","Menelaah hasil dan pelaksanaan bersama tim, lalu menentukan komponen yang perlu diuji ulang dengan ukuran perubahan membaca."]],[4,"KEPRIBADIAN","Orang tua seorang siswa yang memiliki pengaruh besar di masyarakat meminta nilai anaknya ditinjau karena nilai tersebut menentukan beasiswa. Setelah diperiksa, ternyata guru menggunakan rubrik yang sama untuk semua siswa, tetapi terdapat satu komponen penilaian yang dokumentasinya kurang lengkap. Sikap kepala sekolah yang paling tepat adalah:",["Memverifikasi komponen yang kurang terdokumentasi dengan rubrik yang sama dan menjelaskan hasil peninjauan kepada orang tua.","Mempertahankan nilai karena rubrik telah berlaku sama bagi semua siswa dan memperbaiki dokumentasi pada penilaian berikutnya untuk menjaga konsistensi.","Mengulang seluruh penilaian kelas sebelum memeriksa komponen bermasalah agar kesempatan koreksi sama.","Menyerahkan peninjauan sepenuhnya kepada guru agar sekolah menghormati kewenangan profesional penilaian."]],[5,"KEPRIBADIAN","Anda telah mengumumkan perubahan jadwal yang berdampak pada seluruh guru. Sehari kemudian diketahui bahwa data jumlah rombel yang digunakan ternyata belum mutakhir sehingga sebagian keputusan menjadi tidak tepat. Beberapa guru sudah menyesuaikan agenda pribadi berdasarkan jadwal baru. Tindakan terbaik adalah:",["Menjalankan jadwal baru seminggu agar guru tidak segera mengubah agenda pribadi lagi.","Mengakui kesalahan data, mengoreksi bagian jadwal yang terdampak, dan membahas penyesuaian untuk mengurangi gangguan agenda.","Memperbaiki jadwal tanpa menjelaskan kesalahan data agar perhatian guru tetap pada pelaksanaan.","Mengubah bagian yang paling banyak diprotes dahulu dan mempertahankan bagian lain sampai guru menyampaikan kesulitan yang mereka alami."]],[6,"KEPRIBADIAN","Sebuah tangkapan layar di grup WhatsApp menuduh seorang guru mempermalukan siswa di depan kelas. Informasi itu cepat menyebar dan beberapa orang tua meminta tindakan tegas. Guru yang dituduh menyatakan tangkapan layar tersebut tidak menggambarkan kejadian secara utuh. Langkah awal kepala sekolah yang paling tepat adalah:",["Menyampaikan klarifikasi tertulis guru hari itu juga agar orang tua segera mendapat tanggapan.","Membahas tangkapan layar dengan seluruh guru dan menyepakati sikap sekolah sebelum mencari informasi dari siswa serta pihak yang mengetahui kejadian.","Memverifikasi kejadian secara terbatas, memastikan kebutuhan perlindungan, dan menyampaikan pembaruan tanpa mengungkap rincian pribadi.","Menghubungi orang tua untuk menenangkan mereka dan menunda pemeriksaan sampai penyebaran tangkapan layar berkurang agar percakapan lebih kondusif."]],[7,"KEPRIBADIAN","Dalam rapat peningkatan numerasi, Anda menyimpulkan masalah utama berasal dari metode pembelajaran. Seorang guru kemudian menyajikan data tiga kelas yang menunjukkan penurunan terbesar justru terjadi pada siswa dengan tingkat kehadiran rendah. Datanya cukup konsisten, tetapi belum dibandingkan dengan data kelas lain dan belum mengontrol perbedaan kemampuan awal. Sikap kepala sekolah yang paling tepat adalah:",["Memprioritaskan perbaikan kehadiran karena data tiga kelas menunjukkan pola konsisten dan menilai metode mengajar setelah kehadiran siswa membaik.","Menguji hubungan kehadiran, kemampuan awal, dan pembelajaran sebelum mengubah prioritas intervensi numerasi.","Menjalankan perubahan metode dan kehadiran bersamaan di semua kelas agar sekolah segera bertindak sambil mengumpulkan data kemampuan awal siswa.","Mempertahankan diagnosis metode karena data pembanding belum tersedia dan menjadikan kehadiran faktor pendukung."]],[8,"KEPRIBADIAN","Sekolah menghadapi tekanan bersamaan: orang tua menuntut tambahan kelas, guru meminta pengurangan beban administrasi, dan dinas meminta percepatan program tertentu. Sumber daya sekolah terbatas sehingga tidak semua tuntutan dapat dipenuhi. Dasar utama yang paling tepat untuk menentukan prioritas adalah:",["Menimbang kebutuhan siswa, kewajiban sekolah, bukti manfaat, dan kapasitas pelaksanaan untuk menentukan urutan prioritas.","Mengutamakan tuntutan dinas karena kewenangan formal menentukan urutan tanggung jawab sekolah.","Memilih tuntutan dengan dukungan terbanyak agar keputusan mudah diterima dan segera dilaksanakan.","Mendahulukan tuntutan yang cepat dipenuhi agar tekanan berkurang dan sekolah mendapat waktu."]],[9,"KEPRIBADIAN","Seorang guru melakukan kesalahan prosedur untuk pertama kali saat kegiatan siswa. Tidak terjadi kerugian, tetapi jika kesalahan yang sama terulang dapat menimbulkan risiko keselamatan. Guru mengakui kelalaiannya dan menawarkan perbaikan prosedur. Respons kepala sekolah yang paling tepat adalah:",["Memberi teguran tertulis dan meminta prosedur lama diikuti kembali agar tanggung jawab jelas.","Menjadikan pengakuan guru sebagai penutup penanganan dan mengingatkan secara lisan agar kesalahan tidak diulang karena belum terjadi kerugian nyata.","Mengumumkan kesalahan beserta nama guru dalam rapat agar seluruh guru memahami risiko dan konsekuensi ketika prosedur kegiatan tidak dipatuhi.","Mengendalikan risiko, membina secara proporsional, dan menilai usulan perbaikan melalui tindak lanjut yang tercatat."]],[10,"KEPRIBADIAN","Rapor Pendidikan menunjukkan penurunan literasi, sedangkan asesmen internal sekolah relatif stabil. Guru menilai asesmen internal lebih mencerminkan kemampuan siswa karena dilakukan berulang, sementara tim manajemen menilai sumber eksternal lebih objektif. Kedua instrumen mengukur aspek yang tidak sepenuhnya sama dan keputusan program harus dibuat bulan ini. Tindakan paling tepat adalah:",["Menggunakan asesmen internal sebagai dasar utama karena berulang dan memakai Rapor Pendidikan hanya untuk mengonfirmasi masalah yang ditemukan di kelas.","Membandingkan aspek yang diukur dan mutu kedua sumber untuk merumuskan diagnosis yang dapat digunakan bulan ini.","Mengutamakan Rapor Pendidikan karena berasal dari luar sekolah dan menggunakan asesmen internal untuk menentukan siswa yang memerlukan latihan tambahan.","Menjalankan program umum sampai pengukuran berikutnya memastikan sumber yang lebih mewakili kemampuan siswa."]],[11,"KEPRIBADIAN","Menjelang batas waktu pelaporan, ketua panitia meminta Anda menandatangani laporan kegiatan yang baru terlaksana sebagian. Ia beralasan laporan dapat diperbaiki setelah kegiatan selesai dan keterlambatan berpotensi menghambat pencairan program berikutnya. Keputusan yang paling tepat adalah:",["Menandatangani laporan dengan catatan internal agar pencairan berikutnya tetap dapat berjalan.","Mengesahkan laporan setelah panitia menyerahkan rencana penyelesaian sebagai jaminan kegiatan akan selesai.","Melaporkan kemajuan yang sebenarnya dan mengklarifikasi cara pelaporan atau penyesuaian tenggat tanpa menyatakan kegiatan selesai.","Menunggu kegiatan selesai dan menjelaskan keterlambatan hanya apabila penerima laporan meminta keterangan."]],[12,"KEPRIBADIAN","Sekolah memperoleh penghargaan inovasi dan media lokal menyebut Anda sebagai tokoh utama keberhasilan. Padahal gagasan awal berasal dari guru, implementasi dilakukan tim, dan dukungan komite cukup besar. Respons yang paling mencerminkan kepemimpinan matang adalah:",["Mengoreksi pemberitaan mengenai penggagas dan mengakui kontribusi guru, tim, serta komite saat menerima penghargaan.","Menerima pemberitaan tentang pimpinan dan mengakui kontribusi guru serta komite secara internal.","Mengalihkan penerimaan penghargaan kepada penggagas agar atribusi terlihat saat acara penyerahan.","Menyebut warga sekolah secara umum tanpa mengoreksi pemberitaan agar tidak terjadi perbandingan kontribusi."]],[13,"KEPRIBADIAN","Kebijakan baru pembagian jadwal ditolak sebagian besar guru. Mereka menyatakan kriteria yang digunakan tidak adil, sedangkan tim manajemen menilai perubahan diperlukan agar layanan kepada siswa lebih merata. Analisis awal menunjukkan sebagian keberatan memang didukung data, tetapi sebagian lain lebih terkait hilangnya kenyamanan jadwal lama. Implementasi harus dimulai satu minggu lagi. Langkah kepala sekolah yang paling tepat adalah:",["Menunda perubahan sampai mayoritas guru menerima kriteria agar jadwal baru memperoleh dukungan dan tidak memicu penolakan saat mulai berlaku.","Memberlakukan semua kriteria sesuai rencana satu minggu lagi dan menjadwalkan evaluasi sebulan kemudian agar dampak kebijakan dapat dinilai dari pelaksanaan.","Menggunakan kriteria yang disukai bersama agar keberatan dan resistensi guru terselesaikan sekaligus.","Mengoreksi kriteria yang terbukti tidak adil dan menjelaskan penerapannya sambil menjaga pemerataan layanan serta tenggat."]],[14,"KEPRIBADIAN","Setelah satu semester, Anda menerima tiga jenis umpan balik: guru merasa komunikasi pimpinan terlalu cepat, siswa menilai aturan lebih konsisten, dan data layanan menunjukkan waktu penyelesaian masalah lebih singkat. Sikap reflektif yang paling tepat adalah:",["Mempertahankan komunikasi karena data siswa dan layanan positif, lalu mengevaluasi kembali semester berikutnya.","Menguji perbaikan komunikasi sambil memantau konsistensi aturan dan waktu layanan agar manfaat kepemimpinan tetap terjaga.","Mengikuti keinginan guru dahulu dan memeriksa perubahan konsistensi aturan setelah komunikasi diperbaiki.","Mengadakan survei tambahan untuk menyamakan persepsi ketiga pihak sebelum mengubah gaya komunikasi agar arah perbaikan memperoleh kesepakatan menyeluruh."]],[15,"SOSIAL","Sejumlah orang tua memprotes banyaknya tugas rumah karena anak pulang kursus sore. Guru berpendapat tugas diperlukan untuk mengejar target kompetensi. Data sekolah menunjukkan beban tugas sangat berbeda antar kelas dan sebagian siswa mengaku kesulitan mengatur waktu. Langkah kepala sekolah yang paling tepat adalah:",["Mengurangi jumlah tugas dengan persentase yang sama di semua kelas agar keluhan segera tertangani dan siswa memiliki lebih banyak waktu di rumah.","Meninjau tujuan dan beban tugas antar kelas bersama guru serta keluarga untuk menyepakati penugasan yang proporsional.","Mempertahankan tugas sesuai keputusan tiap guru karena target kompetensi harus tercapai dan keluarga dapat menyesuaikan jadwal kursus dengan kebutuhan sekolah.","Meminta komite merumuskan batas tugas yang dapat diterima orang tua lalu menerapkannya pada semua kelas agar guru memiliki pedoman penugasan seragam."]],[16,"SOSIAL","Komite menawarkan bantuan renovasi ruang belajar bernilai besar. Salah satu anggota komite merekomendasikan perusahaan milik kerabatnya sebagai pelaksana. Perusahaan tersebut memiliki portofolio baik dan harga awal tampak kompetitif. Jika bantuan ditolak, renovasi kemungkinan tertunda satu tahun; jika diterima tanpa pengamanan, sekolah berisiko menghadapi konflik kepentingan. Sikap kepala sekolah yang paling tepat adalah:",["Menerima perusahaan yang direkomendasikan dengan memublikasikan harga serta hasil pekerjaan karena keterbukaan transaksi dapat menjaga kepercayaan warga sekolah.","Meminta komite menentukan pelaksana dan mengawasi renovasi secara penuh agar sekolah menerima manfaat tanpa terlibat dalam hubungan keluarga penyedia.","Membandingkan penawaran secara informal melalui anggota komite lalu memilih harga terbaik agar renovasi tidak tertunda dan biaya bantuan tetap efisien.","Memisahkan bantuan dari pemilihan penyedia, mengungkap hubungan keluarga, dan menggunakan proses penilaian yang dapat diperiksa."]],[17,"SOSIAL","Seorang guru muda mengusulkan penggunaan platform digital untuk asesmen formatif. Beberapa guru senior keberatan karena khawatir siswa lebih fokus pada gawai dan guru menjadi tergantung teknologi. Sekolah memiliki perangkat terbatas dan bukti manfaat platform belum tersedia. Langkah paling tepat adalah:",["Menguji platform secara terbatas bersama kedua kelompok guru dengan indikator manfaat dan evaluasi sebelum perluasan.","Membebaskan guru memilih penggunaan lalu membandingkan pengalaman tanpa menetapkan indikator bersama.","Menerapkan platform bergiliran pada semua kelas agar guru belajar langsung selama pelaksanaan.","Menunggu perangkat bagi seluruh siswa agar perbedaan akses tidak memengaruhi hasil implementasi."]],[18,"SOSIAL","Tiga siswa terancam putus sekolah karena masalah ekonomi dan harus membantu orang tua bekerja. Wali kelas sudah memberi kelonggaran kehadiran, tetapi prestasi mereka terus menurun. Sekolah memiliki komite aktif dan beberapa mitra sosial di wilayah sekitar. Strategi paling tepat adalah:",["Melanjutkan kelonggaran dan tugas mandiri agar siswa tetap bersekolah sambil membantu keluarga.","Meminta keluarga berkomitmen mengutamakan kehadiran sebelum sekolah menghubungi komite dan mitra agar bantuan mendorong tanggung jawab orang tua terhadap pendidikan.","Menyusun dukungan ekonomi dan rencana belajar bersama keluarga serta mitra, lalu memantau keberlanjutan pendidikan ketiga siswa.","Menawarkan perpindahan ke layanan pendidikan fleksibel terlebih dahulu agar kebutuhan bekerja dapat dipenuhi tanpa menuntut perubahan layanan belajar di sekolah."]],[19,"SOSIAL","Video pendek tentang aturan sekolah beredar di media sosial dan dipersepsikan sebagai kebijakan diskriminatif. Potongan video tidak memuat penjelasan lengkap, tetapi komentar masyarakat sudah cukup keras. Tindakan komunikasi publik yang paling tepat adalah:",["Mengunggah video lengkap dan meminta masyarakat melihatnya dahulu agar penilaian terhadap sekolah didasarkan pada konteks tanpa penjelasan tambahan dari pimpinan.","Menjelaskan fakta dan dasar kebijakan, membuka dialog, serta memeriksa bagian aturan yang mungkin perlu diperbaiki.","Meminta komite memberi klarifikasi berdasarkan tujuan kebijakan sebelum sekolah memeriksa dampaknya agar komunikasi tidak dianggap sebagai pembelaan kepentingan sekolah.","Menunggu pengaduan resmi sebelum menjelaskan kebijakan agar sekolah tidak memperluas perhatian publik terhadap komentar pada potongan video yang belum lengkap."]],[20,"SOSIAL","Sebuah perusahaan menawarkan platform pembelajaran AI gratis selama satu tahun, termasuk perangkat dan pelatihan. Platform membutuhkan akun individual siswa dan mengumpulkan data penggunaan untuk peningkatan produk. Vendor menyatakan data dianonimkan, tetapi belum menjelaskan retensi, pemrosesan lanjutan, dan kemungkinan penggunaan komersial. Secara pedagogis, platform tampak relevan dengan masalah yang sedang dihadapi sekolah. Langkah paling tepat adalah:",["Memulai pilot satu kelas dengan persetujuan orang tua dan memeriksa rincian pemrosesan selama penggunaan agar bukti manfaat segera tersedia.","Meminta jaminan kerahasiaan serta penghapusan data akhir tahun dan menganggap kedua syarat cukup untuk memulai penggunaan pada siswa.","Menjadikan janji anonimisasi sebagai dasar penerimaan lalu meminta guru memantau manfaat platform untuk menentukan apakah penggunaan perlu diperluas.","Meminta rincian pemrosesan dan perlindungan data, lalu menilai kelayakan pilot bersama manfaat pedagogisnya."]],[21,"SOSIAL","Dua kelompok guru berselisih mengenai penggunaan ruang dan pembagian jadwal. Kedua pihak memiliki data yang masuk akal dan sama-sama merasa dirugikan. Konflik sudah mulai memengaruhi kerja lintas tim, tetapi layanan siswa belum terganggu. Belum ada kriteria pembagian yang disepakati. Kepala sekolah perlu memulihkan kerja sama kedua tim melalui penyelesaian bersama. Tindakan yang paling tepat adalah:",["Menyepakati kriteria bersama, membandingkan kebutuhan kedua tim, dan menguji pengaturan ruang serta jadwal dengan evaluasi.","Menetapkan pembagian berdasarkan data dan pemerataan lalu menjelaskan keputusan agar konflik segera selesai.","Meminta koordinator berunding sendiri dan melibatkan kepala sekolah hanya bila perundingan gagal.","Menggunakan rotasi sama bagi kedua pihak agar pembagian adil tanpa perbandingan kebutuhan kegiatan."]],[22,"SOSIAL","Seorang guru memiliki praktik pembelajaran yang baik, tetapi selalu menolak berbagi karena pernah mendapat kritik tajam saat presentasi internal. Sekolah ingin membangun budaya belajar bersama tanpa membuat guru merasa dipaksa. Langkah yang paling tepat adalah:",["Memberi penghargaan dan menjadwalkan presentasi singkat agar guru memperoleh pengalaman positif.","Meminta bahan ajar tanpa diskusi agar praktik segera dibagikan tanpa mengulang pengalaman kritik.","Menyepakati norma forum yang aman dan memberi pilihan kontribusi sebelum mengajak guru berbagi praktiknya.","Menunggu kontribusi sukarela tanpa membahas kritik atau bentuk berbagi yang nyaman baginya."]],[23,"SOSIAL","Program kebersihan sekolah sudah memiliki petugas, tempat sampah terpilah, dan aturan tertulis, tetapi sampah tetap banyak setelah jam istirahat. Hukuman tambahan pernah diterapkan namun efeknya hanya sementara. Strategi perubahan yang paling tepat adalah:",["Menambah petugas saat istirahat agar sampah terkendali meskipun perilaku siswa belum berubah.","Memetakan perilaku saat istirahat bersama siswa dan menguji perbaikan sistem dengan tanggung jawab serta indikator yang jelas.","Menerapkan konsekuensi lebih konsisten dengan aturan yang sudah ada agar efek hukuman tidak kembali hilang setelah pengawasan terhadap siswa berkurang.","Menyerahkan target kepada wali kelas agar perilaku siswa dikendalikan melalui kelompok kecil."]],[24,"SOSIAL","Sekolah hanya memiliki satu ruang baru. Guru seni mengusulkan studio karena tidak memiliki ruang praktik, guru BK membutuhkan ruang konseling yang menjamin privasi, dan tim literasi mengusulkan perpustakaan mini karena skor literasi rendah. Semua pihak membawa data pendukung, sedangkan penggunaan anggaran harus diputuskan hari itu. Pilihan paling tepat adalah:",["Memilih ruang untuk kebutuhan yang didukung data paling banyak agar keputusan segera selesai dan dapat dipertanggungjawabkan dengan dokumen yang tersedia.","Melakukan voting setelah presentasi agar keputusan mendapat legitimasi kolektif dan anggaran digunakan tepat waktu.","Membagi penggunaan ruang secara bergiliran untuk semua kegiatan agar tidak ada kebutuhan yang dikesampingkan dan setiap pihak memperoleh alokasi yang sama.","Membandingkan ketiga kebutuhan dengan kriteria urgensi, dampak, alternatif ruang, dan jangkauan manfaat sebelum memutuskan hari itu."]],[25,"SOSIAL","Seorang orang tua yang ahli pemrograman menawarkan kelas tambahan gratis untuk siswa. Ia sangat kompeten, tetapi belum pernah bekerja dengan anak dan meminta kebebasan memilih materi sendiri. Banyak siswa tertarik mengikuti. Sikap sekolah yang paling tepat adalah:",["Menyepakati tujuan dan materi, memastikan pendampingan guru serta perlindungan siswa, lalu mengevaluasi kegiatan percobaan.","Mengizinkan satu pertemuan dengan materi pilihan orang tua dan meminta siswa memberi tanggapan sebelum sekolah menetapkan tujuan serta batas kegiatan.","Menyerahkan kelas kepada komite karena kegiatan sukarela dapat dikelola di luar pembelajaran sekolah.","Menolak tawaran sampai orang tua memiliki pengalaman mengajar anak meskipun sekolah dapat menyediakan pendampingan untuk menilai kesesuaian materi yang diajarkan."]],[26,"SOSIAL","Mitra menawarkan program nasional gratis yang mendapat dukungan media dan menyediakan pelatihan guru. Program tersebut bermanfaat, tetapi tidak langsung menjawab prioritas utama sekolah tahun ini dan membutuhkan waktu guru yang cukup besar. Mitra meminta keputusan dalam tiga hari. Tindakan kepala sekolah yang paling tepat adalah:",["Menerima skala kecil dengan desain mitra agar hubungan terjaga tanpa terlalu mengganggu prioritas.","Menerima program penuh karena pelatihan gratis dianggap mengimbangi besarnya waktu guru.","Mengklarifikasi beban, menegosiasikan penyesuaian prioritas, dan memutuskan dalam tiga hari berdasarkan manfaat serta waktu guru.","Menolak langsung karena tidak sesuai prioritas tanpa membahas penyesuaian lingkup dengan mitra."]],[27,"SOSIAL","Sekolah memiliki banyak MoU dengan perguruan tinggi, dunia usaha, dan komunitas. Namun sebagian kerja sama hanya menghasilkan kegiatan seremonial, sementara dua kemitraan kecil justru meningkatkan kualitas pembelajaran secara nyata. Indikator yang paling bermakna untuk menilai kualitas kolaborasi adalah:",["Menilai frekuensi kegiatan dan keaktifan mitra sepanjang tahun agar kerja sama yang terpelihara dapat dibedakan dari dokumen kesepakatan yang tidak digunakan.","Menilai perubahan mutu layanan dan kapasitas sekolah serta manfaat yang bertahan setelah kegiatan bersama berakhir.","Mengukur sumber daya yang diterima sekolah dari tiap mitra agar kontribusi kemitraan dapat dibandingkan berdasarkan dukungan nyata yang sudah diberikan.","Menggunakan kepuasan mitra dan warga sekolah sebagai ukuran utama karena penerimaan kedua pihak menentukan apakah hubungan kolaborasi dapat terus dijalankan."]],[28,"SOSIAL","Anda aktif dalam jejaring kepala sekolah dan sering memperoleh informasi program, pelatihan, serta peluang kerja sama. Namun guru menilai manfaat jejaring tersebut belum terasa di sekolah. Orientasi yang paling tepat dalam mengelola jejaring profesional adalah:",["Meningkatkan keikutsertaan guru pada forum jejaring tanpa memilih agenda tertentu agar lebih banyak warga sekolah memperoleh pengalaman dan informasi secara langsung.","Memusatkan jejaring pada forum yang paling banyak menawarkan program agar sekolah memiliki pilihan dukungan yang luas untuk digunakan pada kesempatan berikutnya.","Mendokumentasikan informasi dan kegiatan jejaring lalu membagikannya kepada guru agar setiap orang menentukan sendiri manfaat yang sesuai dengan pekerjaannya.","Menghubungkan hasil jejaring dengan kebutuhan sekolah dan memastikan pengetahuan atau sumber daya dapat digunakan guru."]],[29,"MANAJERIAL","Sekolah memiliki anggaran terbatas untuk lima program. Dua merupakan kewajiban regulatif, satu sangat populer di kalangan orang tua, sedangkan dua lainnya berdasarkan data berpotensi besar meningkatkan numerasi dan kehadiran. Jika semua dibiayai, kualitas pelaksanaan akan turun. Kepala sekolah harus menetapkan prioritas yang dapat dipertanggungjawabkan. Pendekatan paling tepat adalah:",["Memberi dana minimum kepada semua program agar setiap kebutuhan tetap memperoleh dukungan.","Memenuhi kewajiban secara memadai lalu membandingkan manfaat, biaya, kelayakan, dan risiko program lain untuk menentukan alokasi.","Mengalokasikan sisa dana ke program populer setelah kewajiban terpenuhi karena dukungan orang tua akan mempermudah pelaksanaan dan keberlanjutan program sekolah.","Memilih program termurah setelah kewajiban dipenuhi agar sekolah dapat menjalankan lebih banyak kegiatan dan menjaga keseimbangan layanan pada beberapa bidang."]],[30,"MANAJERIAL","Rapor Pendidikan menunjukkan numerasi rendah. Analisis awal menunjukkan siswa lemah pada pemecahan masalah, tetapi belum jelas apakah penyebabnya ada pada pembelajaran, asesmen, kemampuan prasyarat, atau kehadiran. Guru mengusulkan tambahan jam, komite menawarkan aplikasi, dan pengawas menyarankan pelatihan guru. Waktu penyusunan program hanya dua minggu. Pendekatan diagnosis yang paling tepat adalah:",["Melakukan diagnosis terfokus dalam dua minggu dengan pekerjaan siswa, kehadiran, observasi, dan asesmen prasyarat.","Menambah jam pemecahan masalah dahulu agar siswa memperoleh bantuan sambil diagnosis dilengkapi.","Menguji aplikasi pada kelompok kecil untuk segera mengetahui kemungkinan manfaat solusi teknologi.","Memulai pelatihan guru agar peningkatan kompetensi menjadi sarana menemukan penyebab kelemahan numerasi."]],[31,"MANAJERIAL","Sekolah menjalankan 18 program tahunan. Hampir semuanya terlaksana sesuai jadwal, tetapi hasil belajar, kehadiran, dan kepuasan siswa tidak banyak berubah. Setiap koordinator merasa programnya penting dan khawatir jika kegiatan dihentikan. Tindakan manajerial yang paling tepat adalah:",["Mempertahankan semua program dengan monitoring ketat agar pelaksanaan tepat jadwal menghasilkan perubahan belajar.","Menambah indikator seluruh program dan menunggu setahun agar koordinator membuktikan manfaatnya.","Menilai dampak serta kebutuhan sumber daya tiap program, lalu menggabungkan atau menghentikan yang lemah untuk memperkuat prioritas.","Mengurangi program termahal dahulu agar efisiensi tercapai dan program murah tetap berjalan."]],[32,"MANAJERIAL","Guru mengeluhkan banyak format administrasi yang isinya saling berulang. Sebagian dokumen diwajibkan regulasi, sebagian dibuat sekolah untuk kontrol internal, dan sebagian merupakan kebiasaan lama yang tidak lagi digunakan. Waktu perencanaan pembelajaran mulai tergerus. Respons paling tepat adalah:",["Mendigitalkan semua format yang ada agar pengisian lebih cepat dan kelengkapan administrasi sekolah tetap terpelihara tanpa mengubah struktur dokumen.","Memetakan kewajiban, fungsi, dan duplikasi dokumen untuk menyederhanakan administrasi sambil menjaga kebutuhan pertanggungjawaban.","Membagi pengisian kepada koordinator agar beban merata meskipun dokumen duplikat tetap digunakan.","Menghapus format paling dikeluhkan dahulu sebelum memeriksa fungsi dan kewajiban setiap dokumen."]],[33,"MANAJERIAL","Saat menyusun program tahunan, terdapat tekanan untuk mempertahankan kegiatan lama yang sudah menjadi tradisi. Di sisi lain, data menunjukkan kebutuhan siswa berubah dan beberapa kegiatan tidak lagi relevan. Sumber utama yang paling tepat untuk merancang program adalah:",["Memperbaiki program lama berdasarkan usulan pelaksana agar tradisi tetap terjaga dan kebutuhan siswa yang berubah dapat dimasukkan dalam kegiatan yang sudah dikenal.","Meminta guru dan komite menentukan program melalui kesepakatan bersama agar dukungan pelaksanaan kuat meskipun beberapa kegiatan lama masih dipertahankan.","Mengadaptasi program sekolah lain yang dinilai berhasil agar sekolah memperoleh rancangan siap pakai dan dapat menghemat waktu penyusunan program tahunan.","Menggunakan data siswa dan evaluasi terdahulu untuk memilih program yang selaras dengan tujuan serta kapasitas sekolah."]],[34,"MANAJERIAL","Perpustakaan baru memiliki koleksi cukup baik, tetapi data kunjungan rendah. Guru mengatakan jadwal padat, siswa merasa koleksi kurang sesuai minat, dan pustakawan mengeluhkan kurangnya dukungan program. Langkah yang paling tepat adalah:",["Memeriksa pola penggunaan dan kebutuhan siswa bersama guru serta pustakawan untuk menentukan perbaikan koleksi, jadwal, dan layanan.","Menambah buku populer dahulu untuk mengatasi minat tanpa mengubah jadwal pembelajaran.","Mewajibkan kunjungan mingguan agar fasilitas digunakan dan guru menyediakan waktu khusus.","Mengubah sebagian ruang menjadi tempat belajar bersama agar fasilitas lebih ramai digunakan."]],[35,"MANAJERIAL","Absensi meningkat tajam pada dua tingkat kelas, terutama pada hari tertentu. Wali kelas menduga faktor keluarga, sedangkan siswa menyebut beberapa mata pelajaran terasa terlalu berat. Data belum menunjukkan satu penyebab dominan. Pendekatan penanganan yang paling tepat adalah:",["Mengubah jadwal pelajaran yang dikeluhkan siswa lebih dahulu dan memantau absensi agar sekolah mendapat bukti apakah keberatan siswa berpengaruh pada kehadiran.","Memanggil semua orang tua untuk menegaskan kewajiban hadir pada hari yang bermasalah.","Memetakan absensi menurut siswa dan hari, lalu mengklarifikasi dugaan keluarga serta pembelajaran sebelum memilih dukungan.","Menerapkan penghargaan kehadiran bagi kedua tingkat kelas agar motivasi meningkat sambil wali kelas mengumpulkan penjelasan mengenai hambatan setiap siswa."]],[36,"MANAJERIAL","Sekolah telah menginvestasikan dana besar pada aplikasi pembelajaran. Setelah satu tahun, penggunaan rendah dan dampak pada hasil belajar belum terlihat. Vendor menawarkan diskon perpanjangan 40% disertai pelatihan tambahan. Sebagian tim berpendapat investasi sebelumnya akan sia-sia jika kontrak dihentikan. Sekolah masih memiliki waktu untuk menilai kebutuhan sebelum kontrak berakhir. Dasar keputusan perpanjangan paling tepat adalah:",["Memperpanjang dengan diskon agar pelatihan tambahan membantu penggunaan dan investasi awal tidak sia-sia.","Menilai manfaat dan biaya ke depan serta penyebab penggunaan rendah; keputusan perpanjangan tidak didasarkan pada biaya yang telah keluar.","Memperpanjang hanya untuk sebagian kelas sebagai cara mempertahankan investasi tanpa perlu memeriksa kembali penyebab penggunaan rendah dan alternatif layanan lainnya.","Mengutamakan penawaran termurah untuk menjaga manfaat dana lama tanpa menilai biaya mendatang."]],[37,"MANAJERIAL","Dalam pemeriksaan internal ditemukan beberapa bukti transaksi yang tidak sepenuhnya cocok dengan laporan, meskipun jumlah selisih kecil dan tidak ada indikasi langsung penyalahgunaan. Bendahara menjelaskan kemungkinan terjadi kesalahan pencatatan. Tindakan paling tepat adalah:",["Mengoreksi selisih kecil mengikuti penjelasan bendahara agar laporan selesai lalu memperketat pencatatan pada periode berikutnya untuk mengurangi kesalahan serupa.","Meminta surat tanggung jawab sebagai dasar pengesahan atas selisih yang belum terverifikasi.","Memeriksa hanya transaksi bernilai terbesar agar sumber daya pemeriksaan efisien dan selisih kecil tidak menghambat penyelesaian laporan secara keseluruhan.","Memverifikasi transaksi, mengoreksi laporan berdasarkan bukti, dan memperbaiki kontrol sesuai penyebab ketidakcocokan yang ditemukan."]],[38,"MANAJERIAL","Dua guru memegang banyak tugas tambahan karena memiliki kompetensi khusus, sedangkan beberapa guru lain memiliki beban lebih ringan tetapi belum berpengalaman. Kedua guru mulai menunjukkan tanda kelelahan. Langkah kepala sekolah yang paling tepat adalah:",["Memindahkan tugas yang sesuai kapasitas secara bertahap dengan pendampingan agar beban berkurang dan layanan tetap terjaga.","Memberi penghargaan kepada dua guru dan mempertahankan tugas khusus mereka agar kompetensi yang sudah terbukti tetap menjamin kualitas layanan sekolah.","Membagi semua tugas sama banyak segera agar beban merata dan guru lain memperoleh pengalaman.","Meminta dua guru memilih sendiri tugas yang akan dilepas tanpa pemetaan kapasitas penerima agar pengurangan beban mengikuti kebutuhan mereka yang paling mendesak."]],[39,"MANAJERIAL","Sekolah akan meluncurkan program baru yang disepakati semua pihak, tetapi belum ada baseline maupun indikator keberhasilan. Tim berpendapat indikator dapat ditentukan setelah program berjalan agar lebih realistis. Keputusan tentang kesiapan pengukuran sebelum peluncuran yang paling tepat adalah:",["Meluncurkan program sesuai kesepakatan lalu menetapkan baseline dari hasil bulan pertama agar ukuran keberhasilan mengikuti pengalaman pelaksanaan yang lebih nyata.","Menetapkan baseline, indikator, target, dan cara pengukuran sebelum peluncuran agar perubahan hasil dapat dinilai.","Menggunakan jumlah kegiatan dan peserta sebagai ukuran utama agar tim mudah melaporkan kemajuan tanpa menunda peluncuran program yang sudah memperoleh dukungan.","Menetapkan target kepuasan pengguna sebelum peluncuran dan menambahkan ukuran hasil setelah program berjalan agar rancangan pengukuran tidak membebani tim pelaksana."]],[40,"MANAJERIAL","Evaluasi menunjukkan sebuah kegiatan tahunan tidak meningkatkan indikator akademik yang menjadi tujuan awalnya. Namun guru dan siswa menilai kegiatan tersebut sangat kuat dalam membangun kebersamaan, sesuatu yang tidak diukur dalam evaluasi. Anggaran kegiatan cukup besar dan ada program lain yang membutuhkan dana. Tindakan paling tepat adalah:",["Mempertahankan kegiatan berdasarkan kebersamaan yang dirasakan meskipun tujuan akademik belum tercapai.","Menghentikan kegiatan berdasarkan indikator akademik tanpa menilai manfaat sosial yang belum diukur.","Memeriksa manfaat sosial yang diklaim dan membandingkan biaya serta alternatif sebelum menetapkan kelanjutan atau perubahan kegiatan.","Melanjutkan setahun dengan anggaran sama dan menambah indikator sosial untuk evaluasi berikutnya."]],[41,"MANAJERIAL","Sekolah memperoleh berbagai sumber daya: dana, perangkat, waktu guru, dan dukungan mitra. Kepala sekolah harus menentukan apakah pengelolaan sumber daya sudah baik. Kriteria yang paling tepat adalah:",["Mengutamakan penyerapan dana tepat jadwal agar sumber daya segera digunakan dalam kegiatan sekolah.","Menilai pemerataan antarbidang sebagai ukuran utama agar seluruh unit mendapat kesempatan berkembang.","Mengutamakan kesesuaian rencana awal agar perubahan kebutuhan tidak menyulitkan pertanggungjawaban akhir periode.","Menilai kesesuaian aturan, transparansi penggunaan, dan manfaat sumber daya terhadap prioritas layanan serta pembelajaran."]],[42,"MANAJERIAL","Sekolah menerima tambahan anggaran menjelang akhir tahun. Ada kebutuhan perangkat yang nyata, tetapi waktu pengadaan sempit; ada pula kebutuhan pelatihan yang lebih berdampak namun tidak mungkin selesai tahun ini. Tekanan untuk menyerap anggaran cukup tinggi. Dasar keputusan belanja yang paling tepat adalah:",["Memeriksa kelayakan pelaksanaan dan pertanggungjawaban kebutuhan perangkat dalam waktu tersisa sebelum menyetujui belanja.","Membeli perangkat tercepat diproses agar dana terserap dan pelatihan direncanakan tahun depan.","Membagi dana ke perangkat kecil agar pengadaan cepat dan manfaat tersebar antarunit.","Mendahulukan perangkat yang diusulkan tanpa menilai pemeliharaan agar kesempatan belanja tidak hilang."]],[43,"KEWIRAUSAHAAN","Sekolah memiliki lahan kosong yang dapat menghasilkan pendapatan jika disewakan. Di sisi lain, guru mengusulkan kebun STEM dan siswa ingin mengembangkan produk sederhana yang dapat dijual. Sekolah membutuhkan pengalaman belajar kontekstual tetapi juga menghadapi keterbatasan biaya pemeliharaan. Usulan kegiatan belum memiliki capaian belajar, pembagian peran, atau perhitungan pemeliharaan. Rancangan yang paling memenuhi tujuan pendidikan sekaligus keberlanjutan adalah:",["Menyewakan sebagian lahan untuk mendanai kebun tanpa menetapkan capaian belajar dan peran siswa dahulu agar biaya pemeliharaan segera memiliki sumber pembiayaan.","Membuat kebun di seluruh lahan tanpa menghitung pemeliharaan karena pendidikan merupakan tujuan utama.","Merancang proyek belajar produktif dengan capaian siswa, biaya pemeliharaan, tata kelola, dan ukuran keberlanjutan yang jelas.","Memberi siswa kebebasan usaha dengan pendampingan minimal agar mereka belajar melalui risiko nyata."]],[44,"KEWIRAUSAHAAN","Uji coba aplikasi absensi siswa gagal mencapai target karena guru tidak konsisten menggunakan, koneksi internet kadang terganggu, dan sebagian fitur dianggap terlalu rumit. Konsep dasarnya masih dinilai bermanfaat. Langkah kepala sekolah yang paling tepat adalah:",["Memperbaiki kerumitan fitur, dukungan guru, dan kendala koneksi lalu menguji ulang dengan ukuran keberhasilan yang jelas.","Mewajibkan aplikasi dengan fitur yang sama agar guru terbiasa menggunakannya dan sekolah dapat menilai manfaat setelah tingkat kepatuhan pelaksana meningkat.","Mengganti aplikasi yang digunakan dengan produk lebih sederhana sebelum memeriksa kendala koneksi serta dukungan guru agar proses absensi segera kembali berjalan.","Menghentikan absensi digital karena target gagal tercapai dan kembali ke proses lama tanpa menilai bagian rancangan yang masih dapat diperbaiki."]],[45,"KEWIRAUSAHAAN","Tim sekolah mengusulkan tiga arah kegiatan: usaha untuk menambah pendapatan, penggalangan dukungan mitra, dan uji pendekatan baru untuk mengatasi hambatan belajar. Kepala sekolah ingin memastikan kewirausahaan menjadi cara menciptakan manfaat pendidikan, dengan sumber daya dan risiko yang dikelola. Arah pengembangan paling tepat adalah:",["Membuka kegiatan produktif yang menghasilkan pendapatan lalu menggunakan laba sebagai ukuran keberhasilan sebelum menilai pengalaman belajar yang diperoleh siswa.","Menguji peluang perbaikan belajar, menggerakkan sumber daya, dan mengendalikan risiko untuk menciptakan nilai pendidikan.","Mengutamakan dukungan mitra bagi program yang sudah ada agar keterbatasan dana teratasi tanpa perlu menguji perubahan cara kerja atau hasil pendidikan.","Mencari kegiatan yang berbeda dari sekolah lain dan memublikasikannya agar citra sekolah kuat serta masyarakat terdorong memberikan dukungan terhadap inovasi."]],[46,"KEWIRAUSAHAAN","Minat baca rendah meskipun sekolah memiliki koleksi memadai dan program 15 menit membaca. Observasi menunjukkan siswa membaca sekadar memenuhi kewajiban dan jarang memilih buku sendiri. Kepala sekolah ingin melakukan inovasi. Pilihan paling tepat adalah:",["Menambah buku populer tanpa mengubah pembacaan wajib agar pilihan koleksi menjadi lebih beragam.","Memberi penghargaan jumlah bacaan tanpa memberi siswa ruang memilih buku mereka sendiri.","Menambah durasi wajib agar kebiasaan membaca materi pilihan guru semakin kuat terbentuk.","Menguji rancangan yang memberi pilihan bacaan dan mengukur perubahan keterlibatan berdasarkan minat serta perilaku siswa."]],[47,"KEWIRAUSAHAAN","Seorang guru sangat mahir menggunakan AI untuk membuat bahan ajar. Sebagian guru tertarik, sebagian khawatir terhadap akurasi dan ketergantungan. Sekolah ingin memanfaatkan potensi guru tersebut secara strategis. Langkah paling tepat adalah:",["Mengajak guru tersebut mendampingi sejawat dengan pemeriksaan mutu bahan, batas penggunaan AI, dan evaluasi dampak belajar.","Menugaskannya membuat semua bahan AI agar rekan memperoleh hasil siap pakai yang seragam.","Memberinya kesempatan bereksperimen sendiri sampai hasilnya dinilai baik sebelum membangun panduan bersama agar diskusi kekhawatiran tidak menghambat pengembangan bahan ajar.","Memusatkan bantuan teknis AI padanya agar guru lain tidak perlu menguasai penggunaan platform dan dapat memusatkan perhatian pada pelaksanaan pembelajaran di kelas."]],[48,"KEWIRAUSAHAAN","Sekolah lain berhasil menurunkan absensi melalui aplikasi pengingat, poin penghargaan, dan notifikasi orang tua. Di sekolah Anda, kepemilikan gawai tidak merata dan analisis awal menunjukkan penyebab absensi dominan adalah transportasi dan tanggung jawab keluarga. Kepala sekolah ingin belajar dari praktik tersebut tanpa sekadar meniru. Tindakan paling tepat adalah:",["Mengadopsi poin penghargaan karena tidak memerlukan gawai dan berhasil di sekolah rujukan.","Menunggu akses gawai merata agar model dapat ditiru utuh dan hasilnya dibandingkan.","Menelaah mekanisme praktik rujukan dan menguji adaptasi yang menjawab hambatan transportasi serta tanggung jawab keluarga.","Mencari rujukan serupa dahulu tanpa memakai analisis penyebab absensi di sekolah sendiri."]],[49,"KEWIRAUSAHAAN","Sekolah mengembangkan program berbasis teknologi yang mendapat perhatian media dan disukai guru. Tim ingin menyatakan program berhasil, tetapi belum menetapkan masalah belajar sasaran atau mengukur perubahan proses belajar. Langkah penilaian yang paling tepat adalah:",["Menilai keunikan teknologi sebagai ukuran utama lalu memantau publikasi agar program memiliki ciri berbeda dan sekolah mendapat pengakuan atas kebaruan yang dikembangkan.","Menetapkan masalah sasaran dan menguji perubahan belajar untuk menilai nilai tambah program dibanding praktik sebelumnya.","Mengukur antusiasme guru sebagai bukti keberhasilan utama karena dukungan pengguna menunjukkan program dapat diterima dan memiliki peluang keberlanjutan yang baik.","Meminta sekolah lain mencoba program sebelum mengukur dampak internal agar keberhasilan replikasi menjadi dasar untuk menilai mutu inovasi yang dikembangkan sekolah."]],[50,"KEWIRAUSAHAAN","Sebuah platform AI menawarkan lisensi gratis setahun, pelatihan guru, dan fitur analitik pembelajaran. Vendor meminta akun siswa serta izin memproses data penggunaan untuk meningkatkan model. Setelah tahun pertama biaya akan menjadi berlangganan. Banyak guru tertarik karena fitur terlihat canggih. Sebelum membahas implementasi, pertanyaan strategis paling penting adalah:",["Berapa total biaya setelah masa gratis dan bagaimana sekolah membiayai langganan berikutnya?","Sekolah mana yang telah memakai dan fitur apa yang paling banyak mereka gunakan?","Bagaimana platform diintegrasikan dengan pekerjaan guru, fitur mana yang dipakai terlebih dahulu, dan jadwal pelatihan apa yang memungkinkan penggunaan segera dimulai?","Masalah belajar mana yang perlu diatasi, bukti manfaat apa yang dicari, dan batas data serta risiko apa yang harus dipenuhi?"]],[51,"KEWIRAUSAHAAN","Guru enggan mencoba pendekatan baru karena beberapa inovasi sebelumnya gagal dan kritik terhadap kegagalan cukup keras. Anda ingin membangun kembali budaya inovasi tanpa menurunkan standar akuntabilitas. Langkah paling tepat adalah:",["Membuka eksperimen kecil dengan batas risiko dan refleksi berbasis bukti sambil membedakan kesalahan belajar dari kelalaian.","Memulai dari guru berani dan menampilkan suksesnya tanpa membahas pengalaman kegagalan terdahulu.","Mewajibkan satu inovasi per guru dengan pelaporan rutin agar kebiasaan mencoba terbentuk dan sekolah dapat menilai akuntabilitas dari kepatuhan terhadap kewajiban.","Menunggu semua guru siap agar kegagalan baru tidak kembali merusak kepercayaan organisasi."]],[52,"KEWIRAUSAHAAN","Sekolah ingin membuka laboratorium mini STEM, tetapi anggaran tidak cukup. Ada aset sekolah yang belum optimal, alumni yang bersedia membantu, dan mitra industri yang mungkin mendukung. Tindakan paling tepat adalah:",["Meminta semua kebutuhan kepada mitra besar agar laboratorium dibuka dengan fasilitas lengkap.","Menggalang dana baru dahulu agar program tidak memakai aset untuk kegiatan sekolah lainnya.","Memetakan aset dan kebutuhan minimum lalu menguji laboratorium bertahap dengan bantuan yang sudah dipastikan tersedia.","Menunggu anggaran mencukupi sambil menjaga komunikasi dengan alumni agar pembukaan laboratorium tidak bergantung pada bantuan dan aset yang belum dioptimalkan."]],[53,"KEWIRAUSAHAAN","Program mentoring guru di tiga kelas menunjukkan peningkatan kualitas diskusi siswa dan hasil asesmen. Tim ingin segera memperluas ke seluruh sekolah. Namun belum jelas apakah keberhasilan berasal dari struktur mentoring, kualitas mentor tertentu, atau karakter guru yang terlibat. Keputusan perlu mempertimbangkan momentum dan risiko penurunan kualitas saat diperluas. Langkah paling tepat adalah:",["Memperluas langsung dengan mentor yang sama agar momentum dukungan terjaga dan kualitas mentoring dapat dipertahankan melalui pengalaman pelaksana yang telah berhasil.","Menguji elemen inti pada kelas tambahan, menyiapkan kapasitas mentor, dan memperluas berdasarkan hasil pemantauan.","Mengulang rancangan pada tiga kelas lain tanpa memeriksa perbedaan guru dan mentor agar replikasi memberi pembanding yang dianggap sama dengan uji awal.","Menunda perluasan satu tahun tanpa menetapkan pengujian mekanisme keberhasilan agar bukti perkembangan siswa dalam jangka panjang tersedia sebelum kapasitas mentor ditambah."]],[54,"KEWIRAUSAHAAN","Kebijakan baru mengharuskan perubahan proses kerja sekolah dalam waktu tiga bulan. Guru khawatir beban meningkat dan sebagian prosedur lama masih berjalan baik. Kepala sekolah perlu memimpin adaptasi. Pilihan paling tepat adalah:",["Mengganti semua prosedur sekaligus agar guru tidak menjalankan dua cara kerja selama transisi.","Menunggu petunjuk lebih rinci sebelum memetakan perubahan agar sekolah tidak salah menafsirkan kebijakan meskipun waktu persiapan yang tersedia terus berkurang.","Meminta administrasi menyusun sendiri dan melatih guru menjelang tenggat agar diskusi beban tidak berkepanjangan.","Memetakan proses yang harus berubah dan menyiapkan transisi dalam tiga bulan dengan dukungan peran serta pemantauan hambatan."]],[55,"KEWIRAUSAHAAN","Sekolah mempertimbangkan inovasi yang berpotensi meningkatkan hasil belajar, tetapi menimbulkan tiga risiko: biaya berlebih, beban guru, dan ketidakpatuhan sebagian pengguna. Data awal manfaat masih terbatas. Kepala sekolah tidak ingin terlalu konservatif, tetapi juga tidak ingin mengambil risiko tanpa kendali. Pendekatan paling tepat adalah:",["Menjalankan penuh sambil mencatat risiko agar dampak segera terlihat pada seluruh pengguna.","Menunda sampai manfaat pasti tanpa uji terbatas agar ketidakpastian biaya tidak ditanggung sekolah.","Menguji pada skala terbatas dengan mitigasi biaya dan beban, indikator kepatuhan, serta batas penghentian yang jelas.","Menguji dengan jumlah pengguna kecil tanpa membatasi biaya atau kriteria penghentian karena ukuran pilot dianggap cukup untuk mengendalikan semua risiko utama."]],[56,"KEWIRAUSAHAAN","Sebuah inovasi sekolah berhasil memenangkan lomba dan mendapat banyak kunjungan studi. Namun setelah satu tahun, belum jelas apakah pengalaman belajar siswa berubah. Orientasi akhir yang paling tepat untuk menilai inovasi adalah:",["Menilai perubahan pengalaman serta hasil belajar dan memeriksa apakah manfaatnya bertahan setelah program berjalan.","Menggunakan jumlah sekolah pengunjung sebagai ukuran utama karena ketertarikan pihak lain menunjukkan inovasi dipercaya dan berpotensi memberi manfaat pendidikan secara lebih luas.","Menilai kelangsungan program setelah lomba sebagai bukti utama agar sekolah dapat memastikan inovasi diterima oleh organisasi dan tidak hanya dibuat untuk penghargaan.","Membandingkan biaya program dengan kegiatan sebelumnya sebagai ukuran utama karena penghematan sumber daya dapat menunjukkan nilai inovasi meskipun perubahan belajar belum diukur."]],[57,"SUPERVISI","Saat observasi, guru menjelaskan materi dengan runtut dan nilai ujian kelas relatif tinggi. Namun 80% interaksi berlangsung satu arah, hanya siswa tertentu yang menjawab, dan beberapa siswa tampak mampu meniru prosedur tanpa dapat menjelaskan alasan. Guru berpendapat metode ini efisien untuk mengejar target kurikulum. Umpan balik awal kepala sekolah yang paling tepat adalah:",["Menambah diskusi tanpa membahas bukti respons agar guru segera mencoba peningkatan partisipasi.","Membahas bukti interaksi dan penalaran bersama guru lalu menyepakati perubahan yang akan diuji pada observasi berikutnya.","Meminta guru mengamati kelas lain sebelum menelaah bukti dari kelasnya sendiri.","Menargetkan jumlah siswa menjawab tanpa memeriksa alasan agar partisipasi meningkat dan strategi bertahan."]],[58,"SUPERVISI","Rapat guru membahas rancangan supervisi semester. Ada usulan memeriksa perangkat, menyusun peringkat kinerja, dan menyeragamkan metode mengajar. Kepala sekolah ingin supervisi menghasilkan perbaikan pembelajaran yang dapat ditelusuri. Rancangan supervisi yang paling sesuai adalah:",["Mengutamakan pemeriksaan perangkat sebagai tujuan supervisi agar setiap guru memenuhi kewajiban administrasi sebelum kualitas pembelajaran dibahas dalam pendampingan berikutnya.","Memusatkan supervisi pada peringkat guru agar sekolah menentukan kebutuhan pembinaan menurut posisi kinerja.","Menyeragamkan metode agar mutu antar kelas dikendalikan melalui cara mengajar yang sama.","Menyepakati siklus observasi, refleksi, dan tindak lanjut untuk memperbaiki praktik serta pengalaman belajar siswa."]],[59,"SUPERVISI","Nilai satu kelas jauh lebih rendah dibanding kelas paralel. Guru menyebut komposisi siswa berbeda, wali kelas mencatat absensi lebih tinggi, dan observasi menunjukkan strategi pembelajaran kurang adaptif. Tes awal juga menunjukkan kemampuan prasyarat lebih rendah. Semua faktor dapat saling memengaruhi. Pendekatan diagnosis bersama guru yang paling tepat adalah:",["Memetakan kemampuan awal, kehadiran, dan proses bersama guru untuk memilih hipotesis serta faktor yang dapat diintervensi.","Meniru strategi kelas paralel dahulu sebelum memeriksa kemampuan awal dan kehadiran siswa.","Memprioritaskan absensi sebagai penyebab utama karena siswa harus hadir sebelum dukungan pembelajaran dapat berjalan lalu mengevaluasi faktor lain setelah kehadiran meningkat.","Menambah observasi tanpa membahas data bersama guru sampai bukti proses dianggap lengkap."]],[60,"SUPERVISI","Setelah supervisi, guru menyepakati perubahan strategi, tetapi dua minggu kemudian belum ada perubahan. Guru mengatakan kelasnya terlalu heterogen sehingga rencana sulit diterapkan. Kepala sekolah perlu menindaklanjuti. Pilihan paling tepat adalah:",["Memberi tenggat baru dengan rencana sama agar komitmen guru dibuktikan sebelum dukungan diubah.","Memberikan strategi seragam yang lebih sederhana agar rencana dapat segera diterapkan tanpa memerlukan pembahasan perbedaan kebutuhan siswa dalam kelas tersebut.","Mengklarifikasi hambatan spesifik dan menyepakati penyesuaian strategi, dukungan, serta bukti penerapan yang akan diperiksa.","Meminta guru mencari pelatihan yang sesuai dahulu agar kompetensinya meningkat sebelum kepala sekolah kembali memeriksa penerapan strategi di kelas yang heterogen."]],[61,"SUPERVISI","Catatan observasi menunjukkan guru rata-rata hanya memberi waktu tunggu dua detik sebelum menjawab pertanyaannya sendiri. Guru berpendapat jika menunggu lebih lama kelas menjadi pasif. Data video menunjukkan beberapa siswa sebenarnya mulai mengangkat tangan setelah tiga sampai empat detik. Umpan balik yang paling kuat adalah:",["Menginstruksikan waktu tunggu lebih lama untuk semua pertanyaan agar siswa memiliki kesempatan menjawab tanpa perlu membahas perbedaan jenis pertanyaan dengan guru.","Membahas rekaman waktu tunggu dan mencoba jeda lebih panjang pada pertanyaan tertentu dengan pemantauan respons siswa.","Meminta guru memakai diskusi berpasangan sepanjang pembelajaran agar jeda tidak terasa pasif tanpa menilai perubahan respons terhadap pola waktu tunggu sebelumnya.","Menyerahkan rekaman tanpa kesepakatan tindak lanjut agar perubahan sepenuhnya berasal dari guru sendiri."]],[62,"SUPERVISI","Seorang guru sangat gugup saat disupervisi karena pengalaman sebelumnya bersifat mencari kesalahan. Akibatnya, perilaku mengajarnya saat observasi tidak natural. Agar supervisi menghasilkan data yang lebih bermakna, kepala sekolah sebaiknya:",["Menyepakati tujuan pengembangan pada pra-observasi dan membangun kepercayaan melalui beberapa siklus dengan umpan balik.","Melakukan observasi berikutnya tanpa pemberitahuan agar guru tidak sempat menyiapkan penampilan khusus dan perilaku mengajarnya lebih mencerminkan kegiatan pembelajaran sehari-hari.","Mengurangi observasi serta memakai nilai siswa sampai guru lebih percaya diri menghadapi supervisi.","Mengganti pengamat tanpa membahas tujuan agar hubungan pimpinan tidak memengaruhi perilaku guru."]],[63,"SUPERVISI","Rencana pembelajaran guru lengkap dan materi selesai sesuai jadwal, tetapi selama observasi hanya sekitar 20 persen siswa aktif. Sebagian besar mengikuti instruksi tanpa menunjukkan pemahaman. Fokus utama supervisi berikutnya sebaiknya pada:",["Mengutamakan kesesuaian dengan rencana agar aktivitas rendah dijelaskan melalui dokumen yang tidak terlaksana.","Mengutamakan penguasaan materi guru agar penjelasan lebih runtut dan siswa yang pasif dapat mengikuti pembelajaran tanpa mengubah pola interaksi kelas.","Memeriksa tempat duduk dahulu agar lingkungan diperbaiki sebelum guru meninjau respons pembelajaran.","Menelaah kesempatan siswa berpikir, bukti pemahaman, dan respons guru sebelum menentukan perbaikan interaksi belajar."]],[64,"SUPERVISI","Guru senior dengan hasil belajar baik merasa supervisi tidak lagi diperlukan dan lebih memilih menjadi mentor bagi guru lain. Ia memiliki reputasi kuat sehingga penolakan langsung dapat memicu resistensi. Sikap kepala sekolah yang paling tepat adalah:",["Membebaskan guru dari observasi selama menjadi mentor karena kontribusinya menggantikan pengembangan pribadi.","Menyerahkan kepada pengawas tanpa pembahasan tujuan agar kewajiban formal tidak mengganggu hubungan internal.","Menegaskan pengembangan berlaku bagi semua dan menyepakati fokus menantang yang dipilih bersama guru senior.","Mengganti observasi dengan laporan refleksi berdasarkan reputasi dan hasil belajar yang baik."]],[65,"SUPERVISI","Hasil supervisi enam guru menunjukkan kelemahan serupa: asesmen formatif dilakukan, tetapi hasilnya jarang digunakan untuk menyesuaikan pembelajaran. Masing-masing guru memiliki mata pelajaran berbeda. Sekolah ingin menindaklanjuti kelemahan bersama sekaligus menguji penerapan yang sesuai pada setiap mata pelajaran. Strategi tindak lanjut yang paling efektif adalah:",["Memberi umpan balik sendiri-sendiri tanpa berbagi agar solusi khusus bagi masing-masing mata pelajaran.","Menyelenggarakan belajar bersama dari pekerjaan siswa, menguji respons tiap mata pelajaran, dan membahas perubahan hasil.","Mengadakan satu pelatihan umum tentang asesmen formatif lalu meminta guru menerapkannya sendiri agar pemahaman dasar seragam sebelum sekolah melakukan supervisi berikutnya.","Menyusun prosedur respons yang sama bagi enam guru tanpa membahas pekerjaan siswa agar penggunaan hasil asesmen konsisten dan sekolah mudah memantau kepatuhannya."]],[66,"SUPERVISI","Guru menggunakan metode proyek yang membuat siswa antusias dan menghasilkan produk kreatif. Namun asesmen konsep sebelum dan sesudah proyek hampir tidak berubah. Guru berpendapat tujuan proyek juga mencakup kolaborasi dan kreativitas, sedangkan kepala sekolah melihat ketidaksesuaian dengan tujuan konsep yang ditetapkan. Respons supervisi yang paling tepat adalah:",["Mempertahankan desain proyek dan menambah latihan sesudahnya tanpa menelaah proses agar konsep meningkat sementara pengalaman kreativitas serta kolaborasi siswa tetap terjaga.","Menghentikan proyek dan memakai penjelasan langsung sampai nilai konsep meningkat agar tujuan akademik dipenuhi dahulu sebelum sekolah kembali mengembangkan kreativitas siswa.","Menambah rubrik kolaborasi serta kreativitas tanpa mengubah rancangan agar manfaat proyek yang belum tercatat terlihat dan evaluasi tidak terpaku pada hasil konsep.","Menelaah keselarasan proyek dan asesmen lalu menguji dukungan konsep yang mempertahankan kreativitas serta kolaborasi."]],[67,"SUPERVISI","Dalam satu kelas, sebagian siswa cepat memahami materi sementara sebagian lain tertinggal. Guru menaikkan tingkat kesulitan agar siswa cepat tetap tertantang, tetapi kelompok lain makin pasif. Pendekatan supervisi yang paling tepat adalah:",["Merancang dukungan dan tantangan sesuai kebutuhan kelompok lalu memeriksa kemajuan semua siswa menuju tujuan belajar.","Menurunkan kesulitan tugas untuk seluruh kelas agar kelompok tertinggal kembali aktif dan guru dapat menjaga pembelajaran dengan satu tingkat tuntutan yang sama.","Mempertahankan tuntutan kelas dan menambah latihan di luar jam bagi kelompok tertinggal agar tantangan siswa cepat tidak berubah selama pembelajaran bersama.","Mengelompokkan kemampuan secara tetap agar guru memberi tugas tanpa meninjau perkembangan kebutuhan lagi."]],[68,"SUPERVISI","Setelah melihat rekaman pembelajarannya, guru sendiri menyadari bahwa ia terlalu cepat memberi jawaban kepada siswa. Ia meminta kepala sekolah memberinya strategi yang harus dipakai. Respons yang paling mendukung pengembangan profesional adalah:",["Menentukan satu teknik wajib agar perubahan segera terjadi dan konsistensi penggunaan mudah dinilai.","Mengamati rekan tanpa indikator agar guru memilih strategi yang paling menarik untuk dicoba.","Membantu guru memilih satu strategi sesuai konteks, mencoba dengan indikator jelas, dan merefleksikan bukti pada siklus berikutnya.","Mengobservasi ulang tanpa diskusi strategi agar guru mencari perubahan sendiri berdasarkan kesadaran profesionalnya."]],[69,"SUPERVISI","Seorang guru memiliki administrasi sangat lengkap dan selalu tepat waktu. Namun observasi menunjukkan siswa jarang bertanya, tugas seragam untuk semua, dan sebagian siswa tidak memahami tujuan belajar. Dalam penilaian kualitas pembelajaran, kepala sekolah sebaiknya:",["Memberi bobot yang sama pada administrasi dan keterlibatan agar penilaian tetap seimbang serta tidak mengurangi penghargaan terhadap ketepatan waktu pekerjaan guru.","Mengutamakan bukti proses dan pemahaman siswa, dengan administrasi sebagai pendukung penilaian kualitas pembelajaran.","Mengutamakan administrasi yang lengkap sebagai bukti konsistensi dan menilai keterlibatan kemudian setelah guru menunjukkan semua rencana telah dilaksanakan sesuai dokumen.","Menunggu asesmen akhir sebelum membahas proses agar penilaian tidak didasarkan pada kepasifan yang mungkin belum mencerminkan kemampuan siswa memahami tujuan belajar."]],[70,"SUPERVISI","Sekolah berhasil melaksanakan dua siklus supervisi untuk semua guru. Jadwal terpenuhi, formulir lengkap, guru menilai proses lebih nyaman dibanding tahun sebelumnya, dan sebagian besar rencana tindak lanjut tercatat selesai. Namun belum ada bukti sistematis bahwa praktik mengajar atau pengalaman belajar siswa benar-benar berubah. Ukuran keberhasilan supervisi yang paling bermakna adalah:",["Mengukur persentase guru yang merasa terbantu sebagai ukuran utama karena kenyamanan proses dapat meningkatkan penerimaan terhadap supervisi dan komitmen perbaikan berikutnya.","Menghitung rekomendasi yang selesai sebagai ukuran utama agar tindakan nyata guru setelah observasi menjadi bukti keberhasilan sistem tanpa perlu penelusuran dampak belajar.","Mengukur keterlaksanaan dua siklus dan kelengkapan formulir sebagai ukuran utama karena proses yang konsisten menyediakan dasar untuk pengembangan supervisi pada tahun berikutnya.","Menelusuri perubahan praktik guru dari waktu ke waktu beserta perubahan pengalaman atau hasil belajar siswa."]]];
Q.push(...[[101,"KEPRIBADIAN","Panitia menemukan kuitansi perjalanan dinas yang nilainya lebih besar daripada pengeluaran nyata. Kepala sekolah diminta memeriksa laporan sebelum ditandatangani. Tindakan awal yang paling tepat adalah:",["Mengesahkan laporan berdasarkan kuitansi, lalu meminta penjelasan selisih setelahnya.","Menghapus transaksi yang berselisih dari laporan tanpa memeriksa pengeluaran lainnya.","Meminta laporan disesuaikan dengan pengeluaran nyata dan bukti yang dapat diverifikasi.","Mengembalikan laporan agar nilainya diperbaiki, tanpa meminta bukti pengeluaran nyata."]],[201,"KEPRIBADIAN","Panitia menemukan kuitansi perjalanan dinas yang nilainya lebih besar daripada pengeluaran nyata. Kepala sekolah diminta memeriksa laporan sebelum ditandatangani. Dalam perkembangan berikutnya, Dana kegiatan berikutnya dibutuhkan segera. Bendahara menyatakan selisih akan dikembalikan, sementara bukti asli beberapa transaksi belum ditemukan. Tenggat laporan tinggal satu hari. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Mengesahkan laporan sesuai kuitansi yang tersedia, lalu meminta bendahara menyelesaikan selisih melalui catatan koreksi internal.","Mengembalikan seluruh laporan kepada panitia tanpa menetapkan penanggung jawab verifikasi karena tanggung jawab bukti ada pada pelaksana.","Memisahkan transaksi yang sudah terverifikasi, menahan pengesahan bagian bermasalah, serta melaporkan koreksi dan kebutuhan perpanjangan secara terbuka.","Menunggu semua bukti ditemukan sebelum berkomunikasi dengan pemberi dana agar sekolah tidak dianggap belum siap melapor."]],[102,"KEPRIBADIAN","Dalam rapat, guru menyampaikan bahwa arahan kepala sekolah sering berubah sehingga tim sulit bekerja. Kritik disampaikan dengan nada tinggi. Tindakan awal yang paling tepat adalah:",["Menanggapi substansi kritik dengan tenang dan meminta contoh arahan yang perlu diperjelas.","Meminta guru memperbaiki nada bicara sebelum membahas perubahan arahan.","Menjelaskan alasan setiap perubahan arahan tanpa meminta contoh kesulitan tim.","Meminta tim mengikuti arahan terakhir dan membahas kritik pada rapat berikutnya."]],[202,"KEPRIBADIAN","Dalam rapat, guru menyampaikan bahwa arahan kepala sekolah sering berubah sehingga tim sulit bekerja. Kritik disampaikan dengan nada tinggi. Dalam perkembangan berikutnya, Sebagian contoh ternyata benar, tetapi satu contoh berasal dari pesan yang dipotong. Dua guru saling menyalahkan, dan keputusan jadwal harus selesai sore ini. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Mengakui arahan yang memang tidak konsisten, meluruskan pesan dengan konteks lengkap, dan menetapkan satu keputusan tertulis beserta mekanisme perubahan.","Mengakhiri pembahasan kritik dan menetapkan jadwal melalui tim kecil agar konflik tidak menghambat keputusan hari ini.","Meminta semua guru menuliskan keberatan secara anonim, lalu menunda penetapan jadwal sampai seluruh masukan selesai dianalisis.","Mendelegasikan seluruh klarifikasi kepada wakil kepala sekolah agar hubungan pribadi pimpinan dengan guru tidak memengaruhi proses."]],[103,"KEPRIBADIAN","Kepala sekolah menyadari bahwa undangan rapat yang dikirimnya mencantumkan tanggal salah. Beberapa guru sudah menyesuaikan agenda keluarga. Tindakan awal yang paling tepat adalah:",["Mengirim undangan baru tanpa menjelaskan kesalahan tanggal pada undangan sebelumnya.","Mempertahankan tanggal yang salah agar agenda yang sudah disusun tidak berubah lagi.","Mengakui kesalahan tanggal dan meminta semua guru menyesuaikan agenda keluarga mereka.","Mengakui kesalahan, mengirim koreksi yang jelas, dan mempertimbangkan dampaknya pada peserta rapat."]],[203,"KEPRIBADIAN","Kepala sekolah menyadari bahwa undangan rapat yang dikirimnya mencantumkan tanggal salah. Beberapa guru sudah menyesuaikan agenda keluarga. Dalam perkembangan berikutnya, Sebagian guru bisa hadir pada tanggal yang benar, sebagian tidak. Materi rapat diperlukan untuk keputusan mendesak, dan kepala sekolah ingin tetap menjaga partisipasi. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Melaksanakan seluruh agenda dengan peserta yang hadir karena keputusan berdasarkan undangan koreksi tetap memiliki dasar administrasi.","Menjadwalkan ulang semua pembahasan sampai seluruh guru hadir agar keputusan memperoleh dukungan dan rasa keadilan yang sama.","Menyerahkan keputusan kepada perwakilan guru yang hadir tanpa membahas kembali alasan ketidakhadiran agar rapat tetap produktif.","Mengoreksi undangan, membuka masukan tertulis bagi yang berhalangan, serta membedakan keputusan mendesak dari pembahasan yang dapat dijadwalkan ulang."]],[104,"KEPRIBADIAN","Kerabat kepala sekolah ikut mendaftar sebagai penyedia konsumsi kegiatan. Panitia meminta kepala sekolah menentukan pemenangnya. Tindakan awal yang paling tepat adalah:",["Meminta panitia menilai semua calon, tetapi tetap mengambil keputusan akhir sendiri.","Tidak ikut menilai kerabat, tetapi meminta panitia mengutamakan penyedia yang dikenal.","Meminta kerabat menarik pendaftaran tanpa memberi panitia kesempatan menilai penawaran.","Mengungkap hubungan keluarga dan menyerahkan penilaian kepada panitia dengan kriteria transparan."]],[204,"KEPRIBADIAN","Kerabat kepala sekolah ikut mendaftar sebagai penyedia konsumsi kegiatan. Panitia meminta kepala sekolah menentukan pemenangnya. Dalam perkembangan berikutnya, Kerabat menawarkan harga terendah, tetapi pengalaman layanannya belum teruji. Penyedia lain lebih mahal dan mempunyai rekam layanan baik. Waktu persiapan terbatas. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Memilih penyedia lain untuk menghindari seluruh persepsi konflik kepentingan, meskipun evaluasi penawaran belum dilaksanakan panitia.","Mengundurkan diri dari penilaian, meminta panitia membandingkan harga dan risiko layanan dengan bukti yang sama, serta mendokumentasikan alasan pilihan.","Menggunakan penawaran termurah sebagai dasar keputusan awal, lalu meminta panitia memastikan kualitas pada saat kegiatan berlangsung.","Meminta pengawas memilih penyedia tanpa memberi rekomendasi kriteria agar keputusan benar-benar berasal dari pihak yang lebih independen."]],[105,"KEPRIBADIAN","Kepala sekolah menerima pesan anonim bahwa seorang guru meninggalkan kelas saat pelajaran berlangsung. Belum ada bukti pendukung. Tindakan awal yang paling tepat adalah:",["Meminta guru menjelaskan tindakannya dengan menganggap isi pesan sudah benar.","Mengabaikan pesan karena pengirimnya tidak menyebutkan identitas.","Melakukan klarifikasi dan memeriksa informasi sebelum menetapkan tindak lanjut.","Mengirim pesan tersebut kepada semua guru agar mereka menilai kebenarannya."]],[205,"KEPRIBADIAN","Kepala sekolah menerima pesan anonim bahwa seorang guru meninggalkan kelas saat pelajaran berlangsung. Belum ada bukti pendukung. Dalam perkembangan berikutnya, Rekaman menunjukkan guru keluar, tetapi kelas sedang didampingi guru pengganti. Catatan penugasan pengganti tidak lengkap dan pengirim pesan meminta tindakan segera. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Memberikan teguran karena keberadaan guru di luar kelas sudah terbukti, kemudian memeriksa penugasan guru pengganti untuk melengkapi laporan.","Menutup laporan karena kelas terbukti memiliki pendamping sehingga kekurangan catatan penugasan dapat diselesaikan kemudian secara informal.","Mengumumkan hasil rekaman di forum guru agar semua pihak dapat menilai bersama apakah tindakan guru tersebut dapat diterima.","Memisahkan fakta keluar kelas dari dugaan penelantaran, memverifikasi pendampingan siswa, dan memperbaiki pencatatan penugasan sebelum menentukan pembinaan."]],[106,"KEPRIBADIAN","Seorang siswa meminta bantuan karena sering diejek teman. Ia takut laporan diketahui banyak orang. Tindakan awal yang paling tepat adalah:",["Meminta siswa menceritakan pengalamannya di depan teman agar ejekan berhenti.","Menyarankan siswa menghindari teman yang mengejek sebelum sekolah menindaklanjuti.","Menjanjikan laporan tidak akan disampaikan kepada siapa pun sehingga tidak perlu tindak lanjut.","Mendengarkan siswa, membatasi penyebaran laporan, dan menyiapkan langkah perlindungan."]],[206,"KEPRIBADIAN","Seorang siswa meminta bantuan karena sering diejek teman. Ia takut laporan diketahui banyak orang. Dalam perkembangan berikutnya, Siswa meminta tidak ada tindakan apa pun, tetapi ejekan mengandung ancaman. Orang tua terduga pelaku adalah tokoh masyarakat dan menolak label perundungan. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Menghormati permintaan siswa untuk merahasiakan semuanya sambil memberi dukungan individual agar ia lebih mampu menghadapi situasi tersebut.","Memanggil kedua keluarga ke forum bersama sejak awal agar kesepakatan cepat diperoleh sebelum sekolah memulai pemeriksaan terpisah.","Memindahkan siswa ke kelas lain atas pertimbangan keamanan, kemudian menyelesaikan hubungan antarkeluarga melalui mediasi informal.","Menjelaskan batas kerahasiaan demi keselamatan, menjalankan perlindungan segera, dan memeriksa fakta secara adil melalui mekanisme penanganan yang berlaku."]],[107,"KEPRIBADIAN","Guru berprestasi meminta izin tidak mengikuti piket yang sudah disepakati. Tidak ada alasan kedaruratan atau penugasan lain. Tindakan awal yang paling tepat adalah:",["Mengizinkan tidak piket sebagai bentuk penghargaan atas prestasinya.","Menyerahkan keputusan kepada guru tersebut karena ia memahami kontribusinya sendiri.","Meminta guru lain menggantikan piket agar permintaan guru berprestasi tetap terpenuhi.","Menjelaskan bahwa prestasi tidak menghapus tanggung jawab yang berlaku bagi seluruh guru."]],[207,"KEPRIBADIAN","Guru berprestasi meminta izin tidak mengikuti piket yang sudah disepakati. Tidak ada alasan kedaruratan atau penugasan lain. Dalam perkembangan berikutnya, Guru tersebut sedang menyiapkan lomba tingkat nasional atas nama sekolah. Tidak ada penugasan tertulis, sementara guru lain keberatan terus menggantikan piketnya. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Memberikan pembebasan sementara sampai lomba selesai karena prestasi nasional membawa manfaat bagi reputasi seluruh warga sekolah.","Mempertahankan jadwal piket tanpa penyesuaian agar tidak ada perlakuan khusus, lalu meminta guru mengatur sendiri persiapan lombanya.","Memformalkan prioritas penugasan, menilai kebutuhan penyesuaian beban secara transparan, dan menyepakati pengganti yang adil untuk jangka waktu tertentu.","Meminta guru mencari pengganti melalui kesepakatan pribadi agar kepala sekolah tidak perlu mengubah pembagian tugas seluruh tim."]],[108,"KEPRIBADIAN","Setelah presentasi program sekolah, kepala sekolah mendapat masukan bahwa penjelasannya sulit dipahami oleh orang tua. Tindakan awal yang paling tepat adalah:",["Mengulang presentasi yang sama agar orang tua lebih terbiasa dengan penjelasannya.","Meminta contoh bagian yang tidak jelas dan memperbaiki cara menjelaskan program.","Membagikan materi presentasi dan menyerahkan pemahaman program kepada orang tua.","Menyederhanakan seluruh materi tanpa mencari bagian yang menimbulkan kebingungan."]],[208,"KEPRIBADIAN","Setelah presentasi program sekolah, kepala sekolah mendapat masukan bahwa penjelasannya sulit dipahami oleh orang tua. Dalam perkembangan berikutnya, Orang tua dengan pendidikan tinggi merasa penjelasan sudah memadai, sedangkan sebagian lainnya tidak memahami biaya dan manfaat. Program segera dimulai. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Mengirim kembali bahan presentasi yang sama kepada seluruh orang tua agar setiap keluarga memperoleh informasi resmi dalam bentuk setara.","Menggunakan contoh dan ringkasan yang mudah diakses, memeriksa kembali pemahaman kelompok berbeda, serta memastikan keputusan orang tua berdasar informasi lengkap.","Meminta perwakilan orang tua menjelaskan program kepada anggota kelompoknya karena mereka lebih memahami kebiasaan komunikasi setempat.","Menyederhanakan presentasi dengan menghapus rincian biaya dan teknis terlebih dahulu agar pesan utama lebih mudah diterima seluruh keluarga."]],[109,"KEPRIBADIAN","Kepala sekolah kecewa karena tugas tim belum selesai pada tenggat yang disepakati. Ia perlu memulai evaluasi. Tindakan awal yang paling tepat adalah:",["Mengawali evaluasi dengan teguran agar tim menyadari pentingnya tenggat.","Memberi tenggat baru kepada seluruh tim tanpa memeriksa pekerjaan yang tersisa.","Menanyakan hambatan dan memeriksa kemajuan pekerjaan sebelum memberi umpan balik.","Meminta tiap anggota menjelaskan siapa yang menyebabkan keterlambatan tim."]],[209,"KEPRIBADIAN","Kepala sekolah kecewa karena tugas tim belum selesai pada tenggat yang disepakati. Ia perlu memulai evaluasi. Dalam perkembangan berikutnya, Sebagian keterlambatan disebabkan perubahan instruksi pimpinan, sebagian oleh pembagian kerja yang tidak berjalan. Tenggat eksternal tidak dapat diperpanjang. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Meminta semua anggota bekerja tambahan secara merata agar pekerjaan segera selesai, lalu mengevaluasi penyebab keterlambatan pada rapat berikutnya.","Mengakui kontribusi perubahan instruksi, memetakan pekerjaan kritis, dan menetapkan pembagian pemulihan yang terukur disertai evaluasi tanggung jawab setelahnya.","Menyerahkan penyelesaian kepada anggota paling berpengalaman agar kualitas dan tenggat terjaga meskipun pembagian kerja awal perlu diabaikan.","Membatasi evaluasi pada pelanggaran tenggat yang dapat dibuktikan agar tanggung jawab personal tidak tercampur dengan perubahan instruksi pimpinan."]],[110,"KEPRIBADIAN","Penyedia perangkat menawarkan hadiah pribadi kepada kepala sekolah setelah pembelian sekolah selesai. Tindakan awal yang paling tepat adalah:",["Menerima hadiah karena proses pembelian sekolah sudah selesai.","Menolak hadiah pribadi dan menjaga hubungan pengadaan tetap profesional.","Menerima hadiah lalu memberi tahu guru agar penerimaannya terbuka.","Meminta hadiah diberikan setelah hubungan dengan penyedia tidak lagi aktif."]],[210,"KEPRIBADIAN","Penyedia perangkat menawarkan hadiah pribadi kepada kepala sekolah setelah pembelian sekolah selesai. Dalam perkembangan berikutnya, Perangkat mengalami gangguan dan penyedia menawarkan servis cepat bersama hadiah tersebut. Sekolah membutuhkan perbaikan sebelum asesmen minggu depan. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Menunda penolakan hadiah sampai perangkat selesai diperbaiki agar hubungan baik dengan penyedia tetap membantu kebutuhan mendesak sekolah.","Memisahkan penolakan hadiah dari tuntutan layanan kontrak, meminta perbaikan terjadwal berdasarkan kewajiban penyedia, dan mendokumentasikan komunikasi.","Menghentikan seluruh komunikasi dengan penyedia setelah tawaran hadiah, lalu mencari teknisi lain meskipun perangkat masih dalam masa layanan.","Mengarahkan hadiah untuk sekolah sehingga tawaran dapat diterima bersama percepatan servis tanpa menimbulkan keuntungan pribadi kepala sekolah."]],[111,"KEPRIBADIAN","Dua catatan kehadiran guru menunjukkan angka berbeda. Kepala sekolah harus memeriksa rekap bulanan. Tindakan awal yang paling tepat adalah:",["Memilih catatan dengan angka kehadiran lebih tinggi agar guru tidak dirugikan.","Menelusuri sumber perbedaan dan mencocokkan bukti sebelum mengesahkan rekap.","Menggunakan rata-rata kedua catatan untuk menyelesaikan rekap bulanan.","Memakai catatan yang paling baru tanpa menelusuri alasan perbedaannya."]],[211,"KEPRIBADIAN","Dua catatan kehadiran guru menunjukkan angka berbeda. Kepala sekolah harus memeriksa rekap bulanan. Dalam perkembangan berikutnya, Catatan elektronik terputus selama tiga hari, sedangkan buku manual ditandatangani setelah kejadian. Keputusan pembayaran tambahan bergantung pada rekap hari ini. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Menggunakan catatan elektronik sebagai standar tunggal karena data digital lebih sulit diubah daripada buku manual yang diisi kemudian.","Menggunakan buku manual sebagai pengganti seluruh data elektronik karena gangguan sistem menyebabkan rekap digital tidak dapat dipercaya sepenuhnya.","Menandai data yang belum pasti, melakukan verifikasi silang dengan bukti penugasan, dan memproses bagian terkonfirmasi melalui prosedur koreksi yang jelas.","Menetapkan angka tengah dari dua rekap sebagai pendekatan sementara agar pembayaran tidak tertunda dan koreksi dapat dilakukan bulan berikutnya."]],[112,"KEPRIBADIAN","Kepala sekolah ingin menilai apakah kebiasaan memberi instruksi tanpa diskusi membantu kinerja tim. Tindakan awal yang paling tepat adalah:",["Mengumpulkan umpan balik tentang pemahaman, inisiatif, dan hasil kerja tim.","Menghitung jumlah instruksi yang selesai diberikan dalam rapat tim.","Menilai keberhasilan dari sedikitnya pertanyaan setelah instruksi diberikan.","Meminta tim menyatakan apakah mereka menyukai gaya kepemimpinan kepala sekolah."]],[212,"KEPRIBADIAN","Kepala sekolah ingin menilai apakah kebiasaan memberi instruksi tanpa diskusi membantu kinerja tim. Dalam perkembangan berikutnya, Pekerjaan rutin selesai lebih cepat, tetapi guru jarang mengusulkan perbaikan. Dalam keadaan darurat, sebagian guru justru meminta arahan lebih tegas. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Mempertahankan gaya instruksi karena penyelesaian tugas merupakan bukti kinerja yang lebih terukur daripada jumlah usulan yang diajukan guru.","Membedakan kebutuhan keputusan darurat dan pengembangan rutin, menguji ruang partisipasi yang terarah, serta memantau kecepatan kerja dan inisiatif secara bersama.","Mengubah seluruh keputusan menjadi musyawarah agar tim merasa memiliki program meskipun kecepatan penanganan keadaan darurat mungkin berkurang.","Memberi kebebasan penuh hanya kepada guru yang sering mengusulkan gagasan agar kesempatan berinisiatif diberikan kepada orang yang sudah siap."]],[113,"KEPRIBADIAN","Kepala sekolah mengetahui namanya dicantumkan sebagai penggagas kegiatan yang sebenarnya disusun seorang guru. Tindakan awal yang paling tepat adalah:",["Menerima pencantuman nama karena kepala sekolah bertanggung jawab atas kegiatan.","Mengucapkan terima kasih kepada guru secara pribadi tanpa mengoreksi atribusi.","Mengoreksi atribusi dan mengakui guru yang menyusun kegiatan.","Mengganti nama penggagas dengan nama sekolah tanpa mengakui penyusun kegiatan."]],[213,"KEPRIBADIAN","Kepala sekolah mengetahui namanya dicantumkan sebagai penggagas kegiatan yang sebenarnya disusun seorang guru. Dalam perkembangan berikutnya, Publikasi sudah tersebar dan sponsor mengaitkan dukungan dengan kepemimpinan kepala sekolah. Guru penggagas khawatir koreksi dianggap mempermalukan sekolah. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Mengakui guru dalam rapat internal saja agar kontribusinya tetap dihargai tanpa mengganggu narasi publik yang mendukung hubungan sponsor.","Menyerahkan seluruh pengakuan kepada guru penggagas sehingga publik memahami bahwa kepala sekolah tidak mengambil kredit atas gagasan orang lain.","Menunda koreksi sampai kegiatan selesai agar sekolah memiliki hasil yang kuat sebelum membahas kembali pembagian kontribusi dalam publikasi.","Menyampaikan apresiasi dan koreksi proporsional melalui kanal yang sama, menjelaskan peran pimpinan dan tim, serta memastikan pengakuan dalam dokumentasi resmi."]],[114,"KEPRIBADIAN","Seorang guru ingin menampilkan nilai seluruh siswa di papan pengumuman untuk memotivasi mereka. Tindakan awal yang paling tepat adalah:",["Mengizinkan penayangan nilai agar siswa mengetahui posisi mereka di kelas.","Menampilkan nilai tanpa nama tetapi tetap mencantumkan nomor urut siswa.","Menayangkan nilai selama satu hari saja untuk membatasi dampaknya pada siswa.","Meninjau cara pemberian umpan balik agar perkembangan siswa didukung tanpa mempermalukan mereka."]],[214,"KEPRIBADIAN","Seorang guru ingin menampilkan nilai seluruh siswa di papan pengumuman untuk memotivasi mereka. Dalam perkembangan berikutnya, Guru membawa data bahwa rata-rata nilai meningkat, tetapi siswa dengan nilai rendah makin absen. Sebagian orang tua menyukai keterbukaan peringkat. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Menganalisis dampak pada kelompok berbeda, menghentikan publikasi yang merugikan siswa, dan menggantinya dengan umpan balik perkembangan serta dukungan belajar terarah.","Melanjutkan publikasi dengan hanya menampilkan siswa peringkat atas agar motivasi tetap terjaga sementara siswa lain tidak disebut secara langsung.","Meminta persetujuan mayoritas orang tua sebelum menentukan kelanjutan publikasi agar kebijakan memperoleh legitimasi dari keluarga peserta didik.","Menghapus seluruh bentuk perbandingan hasil belajar termasuk analisis internal agar sekolah konsisten melindungi siswa dari tekanan peringkat."]],[115,"SOSIAL","Orang tua menanyakan alasan perubahan jadwal masuk sekolah. Penjelasan resmi belum disampaikan kepada mereka. Tindakan awal yang paling tepat adalah:",["Menjelaskan alasan perubahan dan menyediakan saluran untuk pertanyaan orang tua.","Meminta orang tua menunggu sampai terbiasa dengan jadwal baru.","Menyampaikan jadwal baru kembali tanpa menjelaskan alasan perubahannya.","Meminta guru menjawab sendiri pertanyaan orang tua tanpa menyamakan penjelasan."]],[215,"SOSIAL","Orang tua menanyakan alasan perubahan jadwal masuk sekolah. Penjelasan resmi belum disampaikan kepada mereka. Dalam perkembangan berikutnya, Perubahan membantu transportasi sebagian siswa tetapi menyulitkan keluarga yang bekerja pagi. Data kebutuhan transportasi belum lengkap dan jadwal baru berlaku minggu depan. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Memetakan dampak pada kelompok keluarga, menilai alternatif penyesuaian yang layak, dan mengomunikasikan keputusan beserta dukungan serta waktu evaluasinya.","Mempertahankan jadwal baru berdasarkan manfaat transportasi yang sudah diketahui dan mengatasi keberatan keluarga satu per satu sesudah penerapan.","Membatalkan perubahan sampai semua keluarga menyepakati jadwal agar sekolah tidak memulai kebijakan yang masih memunculkan keberatan.","Mengadakan pemungutan suara seluruh orang tua lalu menjalankan jadwal yang paling banyak dipilih tanpa membedakan besarnya dampak bagi kelompok tertentu."]],[116,"SOSIAL","Dua guru berselisih tentang penggunaan ruang kelas untuk kegiatan tambahan. Keduanya merasa sudah mendapat izin. Tindakan awal yang paling tepat adalah:",["Memberikan ruang kepada guru yang lebih dulu menyampaikan keluhan.","Memeriksa kesepakatan penggunaan ruang dan memfasilitasi penyelesaian berdasarkan kebutuhan kegiatan.","Membagi waktu penggunaan sama rata tanpa memeriksa izin dan kebutuhan kegiatan.","Meminta kedua guru mencari ruang lain agar perselisihan segera berakhir."]],[216,"SOSIAL","Dua guru berselisih tentang penggunaan ruang kelas untuk kegiatan tambahan. Keduanya merasa sudah mendapat izin. Dalam perkembangan berikutnya, Satu kegiatan wajib berlangsung besok, satu lainnya melibatkan tamu yang sudah datang dari luar kota. Catatan izin pimpinan saling bertentangan. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Memberikan ruang kepada kegiatan wajib karena dasar tugasnya lebih kuat, kemudian meminta kegiatan tamu menyesuaikan seluruh rencana secara mandiri.","Memberikan ruang kepada kegiatan tamu demi menjaga hubungan eksternal dan meminta kegiatan wajib mencari pengganti pada jadwal berikutnya.","Mengakui konflik izin, memeriksa ruang atau waktu alternatif, dan menetapkan prioritas layanan berdasarkan urgensi sambil memperbaiki satu sistem pemesanan.","Menyerahkan keputusan kepada kedua guru karena kesepakatan yang mereka susun sendiri lebih berpeluang diterima daripada penentuan prioritas pimpinan."]],[117,"SOSIAL","Sekolah ingin melibatkan warga dalam kegiatan membaca anak. Kepala sekolah perlu memulai kemitraan. Tindakan awal yang paling tepat adalah:",["Mengidentifikasi mitra dan menyepakati tujuan kegiatan yang mendukung kebutuhan belajar siswa.","Memilih warga yang bersedia membantu lalu menyerahkan rancangan kegiatan kepada mereka.","Menetapkan jadwal kegiatan lebih dahulu sebelum membahas kebutuhan belajar anak.","Mengundang sebanyak mungkin warga tanpa menetapkan tujuan dan peran kemitraan."]],[217,"SOSIAL","Sekolah ingin melibatkan warga dalam kegiatan membaca anak. Kepala sekolah perlu memulai kemitraan. Dalam perkembangan berikutnya, Kelompok warga siap membantu, tetapi mereka mengusulkan materi promosi organisasi. Guru kekurangan waktu pendampingan dan akses buku berbeda antardusun. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Menerima rancangan mitra lebih dahulu agar bantuan segera berjalan, lalu menilai keberatan tentang materi promosi setelah kegiatan pertama selesai.","Menyepakati batas konten pendidikan, membagi peran pendampingan, dan merancang akses bergilir yang dievaluasi berdasarkan partisipasi serta manfaat belajar.","Membatasi kemitraan pada dusun yang memiliki banyak buku sehingga kegiatan dapat menunjukkan hasil sebelum diperluas ke wilayah yang sulit dijangkau.","Meminta seluruh kegiatan dikelola guru agar kendali pendidikan terjaga, sementara warga cukup membantu pengadaan buku dan kebutuhan logistik."]],[118,"SOSIAL","Orang tua keberatan anaknya diberi tugas kelompok pada akhir pekan. Guru ingin mendengar kebutuhan keluarga. Tindakan awal yang paling tepat adalah:",["Mempertahankan tugas akhir pekan karena tujuan belajarnya sudah ditentukan.","Menghapus semua tugas kelompok akhir pekan tanpa membahas kendala keluarga.","Mengizinkan siswa memilih tidak ikut tanpa mencari cara mencapai tujuan tugas.","Membahas tujuan tugas dan kendala waktu untuk mencari pengaturan yang memungkinkan siswa berpartisipasi."]],[218,"SOSIAL","Orang tua keberatan anaknya diberi tugas kelompok pada akhir pekan. Guru ingin mendengar kebutuhan keluarga. Dalam perkembangan berikutnya, Tugas penting untuk asesmen kolaborasi, tetapi siswa bekerja membantu keluarga dan sebagian tidak mempunyai internet. Tenggat pelaporan nilai tinggal lima hari. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Mengganti tugas kelompok menjadi tugas individual bagi semua siswa agar tenggat nilai dapat dipenuhi tanpa bergantung pada waktu keluarga.","Memberikan tambahan tenggat hanya kepada keluarga yang mengajukan keberatan tertulis agar penyesuaian dapat dipertanggungjawabkan melalui dokumen.","Mempertahankan tujuan kolaborasi melalui waktu dan media alternatif di sekolah, menetapkan bukti kontribusi individual, serta menjelaskan pengaturan yang adil.","Meminta siswa yang memiliki internet menjadi penghubung kelompok sehingga tugas akhir pekan tetap dapat berjalan sesuai rancangan awal guru."]],[119,"SOSIAL","Perwakilan komite dan guru berbeda pendapat tentang prioritas kegiatan sekolah. Diskusi mulai beralih ke kritik pribadi. Tindakan awal yang paling tepat adalah:",["Meminta kedua pihak menghentikan kritik pribadi lalu segera memilih salah satu usulan.","Mengembalikan pembahasan pada kebutuhan siswa dan kriteria prioritas yang disepakati.","Memberi waktu bicara sama panjang tanpa menyepakati dasar pemilihan prioritas.","Menunda pembahasan sampai kedua pihak sepakat sendiri mengenai kegiatan."]],[219,"SOSIAL","Perwakilan komite dan guru berbeda pendapat tentang prioritas kegiatan sekolah. Diskusi mulai beralih ke kritik pribadi. Dalam perkembangan berikutnya, Komite menawarkan dana untuk acara besar, sedangkan guru memerlukan dukungan pemulihan belajar. Dana hanya tersedia jika acara tetap dilaksanakan. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Menerima dukungan acara karena sumber daya tambahan dapat meningkatkan hubungan masyarakat, lalu mencari sumber lain untuk pemulihan belajar.","Menolak dana yang bersyarat tanpa melanjutkan dialog agar keputusan program sekolah tidak pernah dipengaruhi oleh preferensi pemberi dukungan.","Menegosiasikan ruang dukungan untuk kebutuhan belajar, menghitung konsekuensi setiap pilihan, dan menjaga keputusan sekolah berbasis manfaat serta batas kewenangan komite.","Membagi waktu kegiatan sama banyak untuk acara dan pemulihan belajar sebagai kompromi yang menunjukkan penghargaan terhadap kedua kelompok."]],[120,"SOSIAL","Seorang siswa baru sulit bergaul karena bahasa sehari-harinya berbeda dari teman sekelas. Tindakan awal yang paling tepat adalah:",["Membangun kegiatan perkenalan yang menghargai perbedaan dan membantu komunikasi siswa.","Meminta siswa memakai bahasa teman sekelas agar lebih cepat menyesuaikan diri.","Membiarkan siswa mengenali teman sendiri agar interaksinya berlangsung alami.","Meminta teman sekelas selalu menerjemahkan percakapan tanpa kegiatan perkenalan bersama."]],[220,"SOSIAL","Seorang siswa baru sulit bergaul karena bahasa sehari-harinya berbeda dari teman sekelas. Dalam perkembangan berikutnya, Guru menilai siswa harus cepat menyesuaikan diri, sementara anak mulai menolak sekolah. Teman sebaya sebenarnya ingin membantu tetapi sering salah memahami ucapannya. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Memberikan latihan bahasa tambahan sebelum anak mengikuti seluruh kegiatan kelompok agar risiko salah paham dengan teman dapat dikurangi.","Meminta teman sekelas selalu menggunakan bahasa siswa baru agar ia merasa diterima selama proses penyesuaian di lingkungan sekolah.","Menempatkan siswa bersama teman yang memiliki latar bahasa sama sampai ia cukup percaya diri untuk berinteraksi dengan kelompok lain.","Mendampingi adaptasi bahasa dan relasi melalui dukungan teman terarah, berkomunikasi dengan keluarga, dan memantau rasa aman serta partisipasi belajar."]],[121,"SOSIAL","Perusahaan menawarkan bantuan buku dengan syarat logo produknya muncul pada setiap lembar tugas siswa. Tindakan awal yang paling tepat adalah:",["Menerima bantuan karena buku bermanfaat dan logo hanya bagian dari lembar tugas.","Menolak bantuan langsung tanpa menilai syarat logo dan kebutuhan buku sekolah.","Memeriksa kesesuaian syarat bantuan dengan kepentingan pendidikan dan batas kemitraan sekolah.","Membatasi ukuran logo agar kecil tanpa membahas tujuan dan batas kemitraan."]],[221,"SOSIAL","Perusahaan menawarkan bantuan buku dengan syarat logo produknya muncul pada setiap lembar tugas siswa. Dalam perkembangan berikutnya, Sekolah sangat kekurangan buku. Perusahaan bersedia mengurangi ukuran logo tetapi tetap meminta data kontak keluarga siswa untuk tindak lanjut promosi. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Menerima logo kecil dan meminta orang tua menyatakan persetujuan pemberian data agar kebutuhan buku serta keputusan keluarga tetap terakomodasi.","Menerima buku sambil hanya menyerahkan kontak keluarga yang aktif di komite karena data kelompok tersebut lebih mudah dikonfirmasi sekolah.","Menolak semua bantuan perusahaan agar sekolah terhindar dari kemungkinan pengaruh komersial meskipun bentuk dukungan lain tanpa promosi masih dapat dibahas.","Menolak pemanfaatan data keluarga untuk promosi, menegosiasikan bantuan tanpa syarat yang merugikan, dan mencari alternatif bila batas pendidikan tidak diterima."]],[122,"SOSIAL","Kelompok orang tua membuat informasi sekolah versi sendiri di media sosial. Beberapa rincian kegiatan keliru. Tindakan awal yang paling tepat adalah:",["Meminta semua orang tua berhenti membagikan informasi sekolah di media sosial.","Mengirim rincian yang benar hanya kepada pembuat unggahan tanpa klarifikasi bersama.","Membiarkan unggahan tersebut karena informasi berasal dari kelompok orang tua.","Menyediakan klarifikasi yang mudah dibagikan dan mengarahkan mereka pada sumber resmi sekolah."]],[222,"SOSIAL","Kelompok orang tua membuat informasi sekolah versi sendiri di media sosial. Beberapa rincian kegiatan keliru. Dalam perkembangan berikutnya, Informasi keliru menimbulkan tuduhan pungutan, tetapi dokumen sekolah sendiri ambigu. Pengurus kelompok tidak ingin dianggap menyebarkan kebohongan. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Mengirim bantahan rinci di semua grup dan meminta pengurus menarik unggahan sebelum sekolah membahas kembali kekurangan dokumen internal.","Mengoreksi dokumen ambigu, menjelaskan fakta tanpa mempermalukan pengurus, dan menyepakati cara pembaruan informasi melalui kanal resmi serta jaringan orang tua.","Menyelesaikan klarifikasi hanya dengan pengurus kelompok agar tuduhan tidak makin tersebar melalui pernyataan resmi yang menjangkau publik luas.","Menghentikan pembahasan biaya kegiatan sementara dan melanjutkan program lain agar suasana sekolah kembali tenang sebelum klarifikasi diterbitkan."]],[123,"SOSIAL","Dua kelompok siswa saling menyalahkan setelah pertandingan antarkelas. Guru meminta bantuan kepala sekolah. Tindakan awal yang paling tepat adalah:",["Meminta kedua kelompok saling meminta maaf tanpa mendengar kejadian pertandingan.","Mengikuti penjelasan kelompok yang lebih dahulu menghubungi guru.","Mendengarkan pihak terkait dan memfasilitasi penyelesaian dengan aturan yang adil.","Membatalkan pertandingan berikutnya agar kedua kelompok tidak bertemu lagi."]],[223,"SOSIAL","Dua kelompok siswa saling menyalahkan setelah pertandingan antarkelas. Guru meminta bantuan kepala sekolah. Dalam perkembangan berikutnya, Video menunjukkan pelanggaran kedua kelompok tetapi tidak merekam awal kejadian. Satu siswa cedera dan orang tua menuntut sanksi segera. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Memberikan sanksi yang sama kepada kedua kelompok karena video membuktikan keduanya melanggar dan tindakan cepat diperlukan untuk meredakan tuntutan.","Mendahulukan perawatan dan keselamatan, memeriksa kronologi dari beberapa sumber, lalu menentukan pembinaan proporsional serta pemulihan hubungan tanpa mengabaikan tanggung jawab.","Memprioritaskan kesepakatan damai antarkeluarga sebelum menyelidiki kronologi agar proses pemeriksaan tidak memperbesar ketegangan yang sudah terjadi.","Menunda seluruh tindak lanjut sampai video awal kejadian ditemukan agar keputusan sekolah tidak didasarkan pada bukti yang hanya mencakup bagian akhir."]],[124,"SOSIAL","Sekolah mengundang puskesmas untuk membantu edukasi kesehatan. Kepala sekolah perlu memastikan kegiatan bermanfaat. Tindakan awal yang paling tepat adalah:",["Menyepakati materi, sasaran, dan peran berdasarkan kebutuhan kesehatan siswa.","Menyerahkan seluruh rancangan kepada puskesmas tanpa membahas kebutuhan siswa.","Memilih materi sebanyak mungkin agar waktu kegiatan terisi penuh.","Menilai manfaat kegiatan terutama dari jumlah peserta yang hadir."]],[224,"SOSIAL","Sekolah mengundang puskesmas untuk membantu edukasi kesehatan. Kepala sekolah perlu memastikan kegiatan bermanfaat. Dalam perkembangan berikutnya, Puskesmas menawarkan materi standar, sedangkan survei sekolah menunjukkan masalah kesehatan berbeda pada kelompok usia. Waktu narasumber hanya satu jam. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Menggunakan materi standar untuk seluruh siswa karena narasumber kesehatan memiliki dasar keahlian yang lebih kuat daripada hasil survei sekolah.","Menetapkan kebutuhan paling mendesak, membagi materi sesuai usia melalui dukungan guru, dan menyepakati tindak lanjut serta rujukan untuk kasus individual.","Memilih kelompok usia dengan masalah terbanyak sebagai satu-satunya peserta sehingga waktu narasumber digunakan untuk kebutuhan paling tinggi.","Meminta puskesmas memperpanjang waktu kegiatan dan menunda pelaksanaan bila semua kebutuhan usia belum dapat dimasukkan ke satu sesi."]],[125,"SOSIAL","Ayah dan ibu siswa memberikan informasi berbeda tentang izin kegiatan anak. Guru belum mengetahui keputusan keluarga yang sah. Tindakan awal yang paling tepat adalah:",["Menggunakan izin orang tua yang terakhir diterima tanpa klarifikasi lebih lanjut.","Mengklarifikasi perbedaan izin kepada orang tua sebelum menentukan keikutsertaan anak.","Mengizinkan anak ikut karena salah satu orang tua sudah menyetujuinya.","Menyerahkan keputusan kepada siswa tanpa memastikan kejelasan izin keluarga."]],[225,"SOSIAL","Ayah dan ibu siswa memberikan informasi berbeda tentang izin kegiatan anak. Guru belum mengetahui keputusan keluarga yang sah. Dalam perkembangan berikutnya, Kedua orang tua sedang berkonflik dan masing-masing menuntut sekolah mengikuti versinya. Dokumen kewenangan pengasuhan belum lengkap, sementara kegiatan berangkat besok. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Mengikuti izin dari orang tua yang paling sering berkomunikasi dengan sekolah karena hubungan tersebut lebih mudah diverifikasi oleh wali kelas.","Memeriksa dokumen dan prosedur izin yang relevan, menjaga posisi sekolah sebagai pelindung siswa, serta tidak membawa anak ke kegiatan sebelum dasar izin aman jelas.","Meminta anak menentukan orang tua yang izinnya diikuti agar sekolah dapat menghormati keinginan peserta didik tanpa memihak konflik keluarga.","Menganggap izin salah satu orang tua cukup untuk kegiatan sekolah selama tidak ada bukti tertulis bahwa kewenangannya telah dibatasi."]],[126,"SOSIAL","Warga mengeluhkan kebisingan latihan sekolah pada sore hari. Tim siswa sedang mempersiapkan penampilan. Tindakan awal yang paling tepat adalah:",["Meminta warga menoleransi kebisingan sampai penampilan siswa selesai.","Mendengarkan keluhan dan meninjau waktu serta tingkat kebisingan kegiatan.","Menghentikan seluruh latihan sore tanpa memeriksa kemungkinan penyesuaian.","Mengurangi durasi latihan tanpa membahas waktu dan tingkat kebisingan dengan warga."]],[226,"SOSIAL","Warga mengeluhkan kebisingan latihan sekolah pada sore hari. Tim siswa sedang mempersiapkan penampilan. Dalam perkembangan berikutnya, Lokasi alternatif jauh, biaya transportasi terbatas, dan penampilan tinggal tiga hari. Sebagian warga mendukung latihan, tetapi ada tetangga yang sedang sakit. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Menegosiasikan jam dan volume terbatas, memilih bagian latihan yang dapat dipindah, dan membuat satu kontak keluhan dengan komitmen evaluasi harian.","Meneruskan latihan sesuai jadwal karena sebagian besar warga mendukung dan gangguan hanya berlangsung sampai penampilan selesai dalam tiga hari.","Memindahkan seluruh latihan ke lokasi alternatif agar hubungan warga terjaga, kemudian membebankan kebutuhan transportasi pada keluarga peserta kegiatan.","Menghentikan latihan sore sampai warga mencapai kesepakatan sendiri agar sekolah tidak mengambil posisi di antara kelompok yang mendukung dan menolak."]],[127,"SOSIAL","Guru baru jarang terlibat dalam diskusi tim karena merasa pendapatnya kurang dihargai. Tindakan awal yang paling tepat adalah:",["Meminta guru baru menunggu sampai lebih memahami kebiasaan diskusi tim.","Menunjuk guru baru berbicara terakhir setelah semua keputusan disepakati.","Memberi ruang bicara yang setara dan membangun kebiasaan mendengar gagasan berdasarkan isinya.","Menerima setiap usulan guru baru agar ia merasa pendapatnya dihargai."]],[227,"SOSIAL","Guru baru jarang terlibat dalam diskusi tim karena merasa pendapatnya kurang dihargai. Dalam perkembangan berikutnya, Guru baru membawa ide yang baik tetapi belum memahami keterbatasan anggaran. Guru senior mempunyai pengalaman relevan namun mulai menghindari rapat. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Memberi guru baru kendali program agar gagasannya dapat dibuktikan, kemudian mengajak guru senior menilai hasil setelah pelaksanaan pertama.","Meminta guru baru mempelajari semua prosedur sekolah sebelum mengusulkan program agar diskusi tidak dibebani ide yang belum realistis.","Menyerahkan kepemimpinan tim kepada guru senior sambil mewajibkan satu sesi usulan guru baru untuk menjaga keseimbangan peran kedua kelompok.","Memadukan pengalaman senior dan gagasan baru melalui tugas uji kecil, menetapkan batas sumber daya, dan mengevaluasi kontribusi berdasarkan bukti bersama."]],[128,"SOSIAL","Sekolah akan mengadakan perayaan yang mengundang seluruh keluarga. Sebagian keluarga memiliki keterbatasan ekonomi. Tindakan awal yang paling tepat adalah:",["Meminta kontribusi sama besar agar semua keluarga mendapat perlakuan setara.","Menyediakan pilihan tidak hadir bagi keluarga yang sulit membayar kegiatan.","Merancang partisipasi yang tidak mensyaratkan pengeluaran di luar kemampuan keluarga.","Menurunkan biaya perayaan tanpa menilai apakah semua keluarga mampu berpartisipasi."]],[228,"SOSIAL","Sekolah akan mengadakan perayaan yang mengundang seluruh keluarga. Sebagian keluarga memiliki keterbatasan ekonomi. Dalam perkembangan berikutnya, Panitia merencanakan seragam khusus yang disukai banyak orang tua. Sumbangan sukarela belum cukup dan siswa mulai membandingkan kemampuan keluarga. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Mempertahankan seragam dan memberi subsidi hanya kepada keluarga yang mengajukan permohonan agar biaya panitia tetap dapat dihitung dengan jelas.","Memisahkan tujuan kebersamaan dari biaya seragam, menyediakan pilihan partisipasi setara tanpa stigma, serta menyampaikan batas sukarela secara konsisten kepada panitia.","Membatalkan seluruh perayaan karena keterbatasan dana berpotensi menimbulkan perbedaan pengalaman yang tidak adil bagi peserta didik.","Meminta komite menutup kekurangan sementara melalui iuran merata agar tidak ada siswa yang terlihat menerima bantuan khusus saat perayaan."]],[129,"MANAJERIAL","Sekolah memiliki dana terbatas dan dua usulan: memperbaiki atap kelas bocor atau mengganti dekorasi kantor. Prioritas penggunaan dana yang paling tepat adalah:",["Membagi dana sama besar untuk kedua usulan agar semua kebutuhan mendapat bagian.","Memprioritaskan keselamatan dan kelayakan ruang belajar dengan memperbaiki atap yang bocor.","Mengganti dekorasi terlebih dahulu karena biaya pembenahannya lebih mudah dibatasi.","Menunda kedua usulan sampai dana cukup untuk menyelesaikan semuanya sekaligus."]],[229,"MANAJERIAL","Sekolah memiliki dana terbatas dan dua usulan: memperbaiki atap kelas bocor atau mengganti dekorasi kantor. Dalam perkembangan berikutnya, Perbaikan atap memerlukan biaya besar dan sebagian siswa dapat dipindah sementara. Pembenahan kantor termasuk pengamanan dokumen penting yang juga berisiko rusak. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Menggunakan seluruh dana untuk atap karena semua pekerjaan di luar ruang belajar dapat menunggu sampai dana tambahan tersedia.","Membagi dana sama rata pada kedua lokasi agar risiko siswa dan risiko dokumen mendapatkan perhatian serta dukungan yang seimbang.","Menilai risiko kedua kebutuhan, menyediakan pengamanan sementara, dan mengalokasikan dana bertahap pada tindakan yang paling mengurangi dampak layanan serta keselamatan.","Memindahkan siswa dan dokumen sementara, lalu menunda seluruh pengeluaran sampai dana cukup untuk memperbaiki kedua lokasi secara lengkap."]],[130,"MANAJERIAL","Dua kegiatan sekolah dijadwalkan pada waktu yang sama dan memerlukan guru pendamping yang sama. Tindakan awal yang paling tepat adalah:",["Meninjau prioritas dan menyesuaikan jadwal atau penugasan agar pendampingan mencukupi.","Meminta guru bergantian mendampingi kedua kegiatan tanpa menilai kebutuhan pendampingan.","Mempertahankan kedua jadwal dan meminta peserta lebih mandiri selama kegiatan.","Membatalkan salah satu kegiatan tanpa meninjau prioritas dan alternatif jadwal."]],[230,"MANAJERIAL","Dua kegiatan sekolah dijadwalkan pada waktu yang sama dan memerlukan guru pendamping yang sama. Dalam perkembangan berikutnya, Kedua jadwal ditentukan pihak luar. Satu kegiatan wajib, satu lainnya memberi kesempatan langka bagi siswa. Guru pengganti belum berpengalaman. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Memetakan tuntutan pendampingan, memberi dukungan terarah bagi pengganti, dan mempertahankan kegiatan yang layak dengan batas keselamatan serta pembagian tugas jelas.","Membatalkan kegiatan pilihan agar seluruh pendamping berpengalaman dapat dialokasikan pada kegiatan yang bersifat wajib bagi sekolah.","Menugaskan guru pengganti pada kegiatan pilihan tanpa tambahan dukungan karena kesempatan mengikuti kegiatan akan menjadi pengalaman yang dibutuhkannya.","Membagi waktu guru pendamping di antara dua lokasi agar kedua kegiatan memperoleh arahan dari orang yang paling memahami kebutuhan siswa."]],[131,"MANAJERIAL","Kehadiran siswa menurun selama dua minggu. Kepala sekolah ingin menentukan langkah perbaikan. Tindakan awal yang paling tepat adalah:",["Menelusuri pola ketidakhadiran dan penyebabnya sebelum memilih intervensi.","Mengingatkan semua siswa agar hadir tanpa memeriksa pola ketidakhadiran.","Menetapkan target kehadiran baru lalu menunggu perubahan selama dua minggu.","Mengundang seluruh orang tua dan meminta mereka menjamin anak hadir setiap hari."]],[231,"MANAJERIAL","Kehadiran siswa menurun selama dua minggu. Kepala sekolah ingin menentukan langkah perbaikan. Dalam perkembangan berikutnya, Data menunjukkan penyebab berbeda: transportasi, kecemasan belajar, dan kewajiban membantu keluarga. Tim hanya mampu menangani satu kelompok setiap pekan. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Mengelompokkan kebutuhan dan urgensi, memilih dukungan awal bagi risiko paling tinggi, serta menetapkan giliran dan indikator perbaikan untuk setiap penyebab.","Memulai kampanye disiplin kehadiran untuk semua siswa karena pesan seragam akan lebih mudah dilaksanakan dengan kemampuan tim yang terbatas.","Menangani kelompok terbesar terlebih dahulu agar persentase kehadiran sekolah meningkat paling cepat sebelum program menyentuh kelompok lainnya.","Membagikan tanggung jawab kepada wali kelas tanpa prioritas bersama agar setiap kelas bebas menangani penyebab sesuai penilaian gurunya."]],[132,"MANAJERIAL","Kegiatan tambahan sekolah telah berlangsung tiga bulan. Tujuan dan indikator hasil telah ditetapkan sebelum kegiatan dimulai. Kepala sekolah ingin mengetahui manfaatnya bagi siswa. Tindakan awal yang paling tepat adalah:",["Membandingkan pelaksanaan dan hasil dengan tujuan serta indikator yang sudah disepakati.","Mengukur manfaat dari jumlah kegiatan yang sudah terlaksana selama tiga bulan.","Meminta siswa menyatakan suka atau tidak suka tanpa melihat tujuan kegiatan.","Melanjutkan kegiatan karena sudah berjalan tiga bulan tanpa menilai hasilnya."]],[232,"MANAJERIAL","Kegiatan tambahan sekolah telah berlangsung tiga bulan. Kepala sekolah ingin mengetahui manfaatnya bagi siswa. Dalam perkembangan berikutnya, Peserta aktif meningkat, tetapi hasil belajar hanya membaik pada siswa yang sejak awal sudah kuat. Pelaksana mengusulkan perluasan sebelum anggaran berakhir. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Memperluas kegiatan karena pertambahan peserta menunjukkan kebutuhan nyata dan cakupan lebih luas akan memberi peluang munculnya hasil belajar tambahan.","Memisahkan capaian partisipasi dan hasil kelompok berbeda, menguji perbaikan bagi siswa yang belum terbantu, dan menunda perluasan sampai mekanismenya lebih terbukti.","Menghentikan kegiatan karena manfaat belum merata sehingga penggunaan anggaran tidak dapat dinilai adil bagi seluruh kelompok siswa.","Mempertahankan kegiatan untuk siswa yang sudah menunjukkan peningkatan agar dana digunakan pada kelompok dengan bukti manfaat paling jelas."]],[133,"MANAJERIAL","Sekolah membeli perangkat baru tetapi belum mencatatnya dalam daftar inventaris. Tindakan awal yang paling tepat adalah:",["Mencatat jumlah perangkat saja agar daftar inventaris segera diperbarui.","Menyerahkan perangkat kepada pengguna tanpa mencatat lokasi dan tanggung jawabnya.","Menunggu perangkat digunakan beberapa bulan sebelum mencatat kondisi awalnya.","Mencatat identitas, lokasi, penanggung jawab, dan kondisi perangkat dalam inventaris sekolah."]],[233,"MANAJERIAL","Sekolah membeli perangkat baru tetapi belum mencatatnya dalam daftar inventaris. Dalam perkembangan berikutnya, Perangkat sebagian dibeli sekolah dan sebagian dipinjamkan mitra. Dokumen kepemilikan belum lengkap, tetapi perangkat sudah digunakan di beberapa kelas. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Memisahkan status aset dan pinjaman, memverifikasi dokumen, serta membuat catatan penggunaan sementara dan tanggung jawab pemeliharaan tanpa mengklaim kepemilikan yang belum jelas.","Mencatat semua perangkat sebagai aset sekolah agar pendataan penggunaan segera lengkap, kemudian mengoreksi statusnya ketika dokumen mitra diterima.","Menghentikan penggunaan seluruh perangkat sampai dokumen kepemilikan selesai agar sekolah tidak menanggung risiko barang yang statusnya belum pasti.","Mencatat hanya perangkat yang dibeli sekolah dan menyerahkan pencatatan pinjaman kepada mitra karena tanggung jawab kepemilikan berada pada pemberi pinjaman."]],[134,"MANAJERIAL","Rencana kerja sekolah memuat banyak kegiatan tetapi belum memiliki ukuran keberhasilan. Tindakan awal yang paling tepat adalah:",["Menambah rincian jadwal setiap kegiatan sebagai pengganti ukuran keberhasilan.","Menggunakan jumlah peserta sebagai ukuran yang sama untuk semua kegiatan.","Menetapkan keberhasilan berdasarkan selesainya seluruh kegiatan sesuai kalender.","Menetapkan indikator hasil yang sesuai dengan tujuan setiap kegiatan."]],[234,"MANAJERIAL","Rencana kerja sekolah memuat banyak kegiatan tetapi belum memiliki ukuran keberhasilan. Dalam perkembangan berikutnya, Tim memilih indikator mudah dihitung berupa jumlah rapat dan dokumen. Data perkembangan belajar lebih sulit dikumpulkan, sementara laporan kinerja segera diminta. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Memakai jumlah kegiatan sebagai ukuran utama tahun ini karena data tersebut paling konsisten dan memungkinkan perbandingan dengan laporan sebelumnya.","Menghapus semua indikator proses agar laporan hanya berisi hasil belajar meskipun sumber dan kelengkapan datanya belum dapat dipastikan.","Menyerahkan pemilihan indikator kepada setiap pelaksana program agar ukuran keberhasilan disesuaikan dengan data yang paling mudah mereka kumpulkan.","Menggunakan indikator proses yang tersedia bersama indikator hasil sederhana yang relevan, lalu menetapkan cara pengumpulan bukti bertahap tanpa menyamakan aktivitas dengan dampak."]],[135,"MANAJERIAL","Seorang guru cuti beberapa hari. Sekolah perlu memastikan kelasnya tetap memperoleh layanan pembelajaran. Tindakan awal yang paling tepat adalah:",["Membagikan tugas mandiri selama cuti tanpa memastikan bantuan belajar tersedia.","Meminta guru yang cuti tetap mengajar dari jarak jauh sepanjang jadwalnya.","Membagi siswa ke kelas lain tanpa menyesuaikan bahan dan kebutuhan pembelajaran.","Menetapkan pengganti dan bahan pembelajaran yang sesuai dengan kebutuhan kelas."]],[235,"MANAJERIAL","Seorang guru cuti beberapa hari. Sekolah perlu memastikan kelasnya tetap memperoleh layanan pembelajaran. Dalam perkembangan berikutnya, Hanya satu guru tersedia dan sudah memiliki beban penuh. Dua kelas memiliki kebutuhan berbeda, sedangkan bantuan tambahan belum bisa datang minggu ini. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Menggabungkan kedua kelas untuk semua pelajaran agar satu guru dapat mengawasi seluruh siswa melalui satu jadwal dan bahan yang sama.","Membagi hari belajar kedua kelas secara bergantian agar guru tidak mendapat beban tambahan dan tiap kelas memperoleh perhatian penuh saat masuk.","Memberikan tugas mandiri kepada kelas guru yang cuti lalu meminta guru tersedia memeriksa hasilnya setelah tugas utama di kelas sendiri selesai.","Merancang pengaturan sementara yang menjaga pendampingan, memprioritaskan kebutuhan kelompok, dan menyesuaikan tugas guru dengan pemantauan serta dukungan yang tersedia."]],[136,"MANAJERIAL","Laporan orang tua menyebut antrean penjemputan siswa sering tidak tertib. Kepala sekolah akan meninjau prosedur. Tindakan awal yang paling tepat adalah:",["Mengirim imbauan tertib kepada orang tua tanpa meninjau alur penjemputan.","Mengubah jam penjemputan semua kelas sebelum mengidentifikasi titik kemacetan.","Menambah petugas di pintu sekolah tanpa memeriksa sumber masalah antrean.","Mengamati alur penjemputan dan mengidentifikasi titik kemacetan serta risiko keselamatan."]],[236,"MANAJERIAL","Laporan orang tua menyebut antrean penjemputan siswa sering tidak tertib. Kepala sekolah akan meninjau prosedur. Dalam perkembangan berikutnya, Antrean terpusat di satu pintu karena pintu lain dekat jalan ramai. Pemisahan jam pulang menyulitkan keluarga dengan dua anak dan petugas terbatas. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Membuka kedua pintu agar antrean terbagi merata, lalu meminta orang tua membantu mengawasi penyeberangan di pintu yang dekat jalan ramai.","Menerapkan jam pulang berbeda untuk setiap kelas karena pengurangan kepadatan menjadi prioritas meskipun keluarga perlu menyesuaikan jadwal penjemputan.","Menambah imbauan ketertiban pada prosedur yang ada agar sekolah tidak memperkenalkan perubahan yang membutuhkan petugas dan koordinasi tambahan.","Menguji pengaturan antrean dan waktu secara terbatas, menjaga titik aman, serta memantau beban keluarga sebelum menentukan prosedur tetap berdasarkan bukti."]],[137,"MANAJERIAL","Sekolah diminta memilih kebutuhan pelatihan guru untuk tahun berikutnya. Tindakan awal yang paling tepat adalah:",["Menggunakan data kebutuhan kompetensi dan prioritas pembelajaran untuk memilih pelatihan.","Memilih pelatihan yang paling banyak diminati guru tanpa melihat kebutuhan kompetensi.","Memilih tema yang belum pernah diikuti sekolah tanpa memeriksa prioritas pembelajaran.","Membagi kesempatan pelatihan sama rata tanpa menghubungkannya dengan kebutuhan guru."]],[237,"MANAJERIAL","Sekolah diminta memilih kebutuhan pelatihan guru untuk tahun berikutnya. Dalam perkembangan berikutnya, Pelatihan populer tersedia gratis, tetapi kebutuhan terbesar sekolah berbeda. Pelatihan yang relevan berbayar dan hanya bisa diikuti beberapa guru. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Mengikutkan semua guru pada pelatihan gratis karena cakupan peserta yang luas memberi kesempatan manfaat lebih besar dengan biaya sekolah minimal.","Memilih guru yang paling berprestasi untuk pelatihan berbayar karena kesiapan mereka meningkatkan peluang hasil dan menjaga kualitas pelaksanaan program.","Menunda pelatihan berbayar dan meminta guru mempelajari materi sendiri sampai sekolah memiliki dana yang cukup untuk mengikutkan seluruh guru.","Menilai kesesuaian isi dan transfer praktik, memilih peserta strategis untuk kebutuhan utama, dan merancang pendampingan internal agar manfaat tidak berhenti pada peserta."]],[138,"MANAJERIAL","Laporan jumlah siswa pada dua aplikasi sekolah tidak sama. Data akan dipakai untuk perencanaan layanan. Tindakan awal yang paling tepat adalah:",["Menggunakan angka pada aplikasi yang paling sering dibuka oleh petugas.","Mengambil rata-rata kedua jumlah sebagai dasar perencanaan layanan.","Memeriksa identitas dan status siswa untuk menyelaraskan data berdasarkan bukti.","Menyamakan total kedua aplikasi tanpa memeriksa data siswa satu per satu."]],[238,"MANAJERIAL","Laporan jumlah siswa pada dua aplikasi sekolah tidak sama. Data akan dipakai untuk perencanaan layanan. Dalam perkembangan berikutnya, Sebagian siswa pindah tetapi dokumen belum selesai, sebagian hadir tanpa pembaruan aplikasi. Kebutuhan ruang harus diajukan sebelum akhir pekan. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Menggunakan aplikasi resmi sebagai satu-satunya sumber agar usulan konsisten dengan data yang kemungkinan dipakai oleh pihak penerima laporan.","Menggunakan seluruh siswa yang hadir sebagai angka final karena kebutuhan ruang harus mencerminkan kondisi nyata meskipun status administratif belum jelas.","Menunda usulan sampai kedua aplikasi sama agar sekolah tidak mengirim angka yang berpotensi dikoreksi setelah proses perencanaan berjalan.","Memisahkan data administrasi terkonfirmasi dan estimasi layanan aktual, menjelaskan ketidakpastian dalam usulan, serta menetapkan tenggat pemutakhiran bersama penanggung jawab."]],[139,"MANAJERIAL","Rapat koordinasi sekolah berlangsung lama tetapi banyak keputusan tidak ditindaklanjuti. Tindakan awal yang paling tepat adalah:",["Memperpendek durasi rapat tanpa mengubah pencatatan dan tindak lanjut keputusan.","Mengirim daftar keputusan tanpa menetapkan penanggung jawab dan tenggat.","Mencatat keputusan, penanggung jawab, dan tenggat tindak lanjut yang jelas.","Menambah frekuensi rapat agar semua keputusan dibahas kembali secara rutin."]],[239,"MANAJERIAL","Rapat koordinasi sekolah berlangsung lama tetapi banyak keputusan tidak ditindaklanjuti. Dalam perkembangan berikutnya, Catatan tindak lanjut sudah lengkap, tetapi sebagian tugas tumpang tindih dan memerlukan persetujuan beberapa pihak. Tim mengusulkan lebih banyak rapat monitoring. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Menambah rapat mingguan agar penanggung jawab merasa lebih diawasi dan segera menyelesaikan tugas yang belum berjalan sesuai catatan.","Mengurangi jumlah keputusan dalam rapat berikutnya sehingga tim dapat memusatkan tenaga tanpa perlu mengubah prosedur persetujuan yang berlaku.","Memetakan hambatan dan ketergantungan tugas, menyederhanakan jalur keputusan, serta menggunakan monitoring singkat berdasarkan pekerjaan kritis dan bukti kemajuan.","Meminta setiap penanggung jawab menyelesaikan tugasnya sendiri sebelum membahas ketergantungan agar masalah koordinasi tidak menjadi alasan keterlambatan."]],[140,"MANAJERIAL","Sekolah menyimpan dokumen penting hanya pada satu laptop. Tidak tersedia salinan cadangan. Tindakan awal yang paling tepat adalah:",["Menyalin dokumen ke folder lain pada laptop yang sama sebagai cadangan.","Mengirim semua dokumen kepada seluruh guru agar banyak salinan tersedia.","Membuat cadangan yang aman dengan akses sesuai kewenangan dan jadwal pemutakhiran.","Mencadangkan dokumen sekali tanpa menetapkan akses dan pembaruan salinan."]],[240,"MANAJERIAL","Sekolah menyimpan dokumen penting hanya pada satu laptop. Tidak tersedia salinan cadangan. Dalam perkembangan berikutnya, Cadangan awan lebih mudah digunakan, tetapi dokumen memuat data pribadi. Sebagian staf memakai akun bersama dan akses internet tidak selalu tersedia. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Mengunggah semua dokumen ke satu akun bersama agar staf dapat melakukan pembaruan dan mencari salinan dari perangkat yang paling mudah dijangkau.","Mengelompokkan sensitivitas dokumen, membatasi akses dengan akun individual, dan mengatur cadangan terenkripsi serta pemulihan luring yang diuji secara berkala.","Menyimpan salinan pada beberapa perangkat staf agar kehilangan satu laptop tidak mengganggu layanan dan sekolah tidak bergantung pada internet.","Membatasi semua dokumen pada laptop kepala sekolah dan satu penyimpanan fisik terkunci sehingga pengendalian akses lebih mudah dilakukan secara langsung."]],[141,"MANAJERIAL","Pembagian tugas tambahan belum mencantumkan keluaran yang harus diselesaikan tiap petugas. Tindakan awal yang paling tepat adalah:",["Menyepakati peran, keluaran, dan cara pelaporan agar tanggung jawab dapat dipahami.","Membagikan nama petugas untuk setiap tugas tanpa menjelaskan hasil yang diharapkan.","Menetapkan tenggat semua tugas tanpa menyepakati keluaran tiap petugas.","Meminta petugas menentukan sendiri keluaran tanpa pembahasan bersama."]],[241,"MANAJERIAL","Pembagian tugas tambahan belum mencantumkan keluaran yang harus diselesaikan tiap petugas. Dalam perkembangan berikutnya, Tugas tertentu membutuhkan kerja lintas tim. Dua koordinator merasa sama-sama berwenang dan staf menerima arahan yang bertentangan setiap hari. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Menempatkan seluruh staf di bawah satu koordinator agar arahan konsisten meskipun pengetahuan teknis koordinator lainnya tidak lagi memengaruhi keputusan.","Menentukan pemilik keputusan dan batas koordinasi tiap pekerjaan, menyepakati satu alur eskalasi, serta menguji pembagian peran melalui keluaran bersama yang terukur.","Membagi staf menjadi dua kelompok sesuai koordinator agar setiap tim bekerja dengan arahan yang jelas tanpa perlu mendiskusikan batas kewenangan.","Meminta staf memilih arahan yang paling relevan dengan pekerjaan hariannya supaya layanan terus berjalan sambil pimpinan menyelesaikan perbedaan kewenangan."]],[142,"MANAJERIAL","Beberapa siswa sulit mengikuti pembelajaran setelah jadwal pelajaran diubah. Kepala sekolah perlu menilai dampak perubahan. Tindakan awal yang paling tepat adalah:",["Mengembalikan seluruh jadwal lama tanpa memeriksa jenis kesulitan siswa.","Membandingkan pola kesulitan dan pelaksanaan jadwal sebelum menentukan penyesuaian.","Mempertahankan jadwal baru sampai siswa menyesuaikan diri dengan perubahan.","Menanyakan apakah siswa menyukai jadwal baru tanpa melihat pelaksanaan pembelajaran."]],[242,"MANAJERIAL","Beberapa siswa sulit mengikuti pembelajaran setelah jadwal pelajaran diubah. Kepala sekolah perlu menilai dampak perubahan. Dalam perkembangan berikutnya, Nilai rata-rata stabil, tetapi siswa dengan perjalanan jauh makin sering terlambat pada pelajaran inti. Perubahan jadwal membantu ketersediaan guru mata pelajaran. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Mempertahankan jadwal karena nilai rata-rata tetap stabil dan ketersediaan guru merupakan kebutuhan operasional yang sulit diganti pada semester ini.","Mengembalikan seluruh jadwal lama agar siswa dari lokasi jauh memperoleh kesempatan yang sama, lalu meminta guru menyesuaikan penugasan di sekolah lain.","Menilai dampak per kelompok, menegosiasikan alternatif jam atau dukungan kedatangan, dan menguji solusi yang menjaga layanan guru tanpa mengabaikan siswa paling terdampak.","Memberikan tambahan tugas kepada siswa yang terlambat agar mereka dapat mengejar pelajaran inti tanpa mengubah jadwal yang sudah berjalan."]],[143,"KEWIRAUSAHAAN","Sekolah ingin membeli aplikasi pembelajaran baru. Belum ada masalah belajar yang dirumuskan secara jelas. Tindakan awal yang paling tepat adalah:",["Mengidentifikasi kebutuhan belajar sebelum menilai apakah aplikasi menjadi solusi yang sesuai.","Memilih aplikasi dengan fitur paling lengkap lalu menentukan kebutuhan belajarnya.","Membeli aplikasi yang paling mudah digunakan guru tanpa merumuskan masalah belajar.","Mencoba beberapa aplikasi terlebih dahulu tanpa menentukan kebutuhan yang hendak diatasi."]],[243,"KEWIRAUSAHAAN","Sekolah ingin membeli aplikasi pembelajaran baru. Belum ada masalah belajar yang dirumuskan secara jelas. Dalam perkembangan berikutnya, Aplikasi menawarkan analitik menarik dan diskon terbatas. Perangkat siswa tidak merata, sementara guru menyebut masalah utama adalah kualitas umpan balik. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Membeli lisensi saat diskon berlaku lalu mengadakan pelatihan agar guru dapat menemukan penggunaan yang paling sesuai dengan kebutuhan kelasnya.","Membatasi penggunaan pada siswa yang memiliki perangkat sendiri sehingga sekolah dapat memperoleh bukti keberhasilan sebelum mengatasi kesenjangan akses.","Menguji fungsi yang relevan dengan umpan balik pada kelompok terbatas, menilai akses serta biaya menyeluruh, dan mengambil keputusan berdasarkan manfaat dibanding alternatif.","Menolak aplikasi karena perangkat belum merata dan beralih sepenuhnya pada cara lama sampai seluruh siswa memiliki sarana digital yang sama."]],[144,"KEWIRAUSAHAAN","Guru mengusulkan kebun sekolah sebagai tempat belajar sains. Kepala sekolah ingin menilai gagasan tersebut. Tindakan awal yang paling tepat adalah:",["Menghubungkan kegiatan kebun dengan tujuan belajar dan sumber daya yang tersedia.","Menyetujui kebun karena kegiatan di luar kelas akan membuat siswa tertarik.","Menilai gagasan terutama dari keindahan kebun yang dapat ditampilkan sekolah.","Meminta guru membuat kebun dahulu lalu menyesuaikan tujuan belajar setelahnya."]],[244,"KEWIRAUSAHAAN","Guru mengusulkan kebun sekolah sebagai tempat belajar sains. Kepala sekolah ingin menilai gagasan tersebut. Dalam perkembangan berikutnya, Lahan kecil, air terbatas, dan guru ingin menjual hasil kebun. Sasaran pembelajaran belum disepakati, sementara mitra meminta target panen yang tinggi. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Mengikuti target panen mitra agar kebun mempunyai pendapatan yang dapat membiayai kegiatan belajar dan pemeliharaan sekolah pada tahun berikutnya.","Menghapus semua unsur penjualan karena kegiatan yang menghasilkan uang akan mengaburkan tujuan pembelajaran meskipun dapat menjadi materi literasi ekonomi.","Menetapkan nilai pendidikan sebagai tujuan utama, memilih tanaman sesuai keterbatasan, dan membatasi target penjualan agar tidak menggeser kesempatan belajar siswa.","Memilih tanaman paling cepat menghasilkan agar siswa segera melihat hasil nyata, kemudian menyusun keterkaitan pembelajaran setelah kebun mulai berjalan."]],[145,"KEWIRAUSAHAAN","Uji coba kegiatan membaca digital mendapat respons rendah. Tim ingin mengetahui langkah berikutnya. Tindakan awal yang paling tepat adalah:",["Memperpanjang uji coba dengan rancangan yang sama tanpa mencari hambatan penggunaan.","Menghentikan membaca digital karena respons awal menunjukkan minat siswa rendah.","Menambah jumlah bahan bacaan tanpa memeriksa penyebab rendahnya respons.","Memeriksa hambatan dan menggunakan hasil uji coba untuk memperbaiki rancangan."]],[245,"KEWIRAUSAHAAN","Uji coba kegiatan membaca digital mendapat respons rendah. Tim ingin mengetahui langkah berikutnya. Dalam perkembangan berikutnya, Siswa suka isi bacaan tetapi kesulitan masuk aplikasi. Guru menganggap siswa kurang berminat, dan penyedia menawarkan fitur tambahan berbayar. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Menambah fitur berbayar yang lebih interaktif agar minat siswa meningkat dan guru mempunyai alasan baru untuk mengajak mereka menggunakan aplikasi.","Mengganti seluruh bacaan digital dengan bacaan cetak karena respons rendah menunjukkan format digital belum cocok dengan kebiasaan belajar siswa.","Meminta semua siswa mengikuti jadwal akses wajib agar tim memiliki data penggunaan yang cukup sebelum mengubah rancangan uji coba.","Memisahkan masalah akses dari minat, menguji perbaikan paling sederhana pada alur masuk, dan menilai kembali partisipasi sebelum membayar fitur tambahan."]],[146,"KEWIRAUSAHAAN","Sekolah akan mencoba kegiatan praktik di luar kelas yang belum pernah dilaksanakan sebelumnya. Tindakan awal yang paling tepat adalah:",["Melaksanakan kegiatan dalam skala kecil tanpa menilai risiko dan pendampingan.","Menetapkan pendamping setelah kegiatan berlangsung agar kebutuhannya terlihat.","Mengidentifikasi risiko dan menyiapkan pengendalian serta pendampingan sebelum pelaksanaan.","Membatasi waktu kegiatan tanpa memeriksa risiko yang mungkin muncul."]],[246,"KEWIRAUSAHAAN","Sekolah akan mencoba kegiatan praktik di luar kelas yang belum pernah dilaksanakan sebelumnya. Dalam perkembangan berikutnya, Kegiatan memberi peluang belajar kuat tetapi cuaca berubah cepat. Pembatalan menimbulkan biaya, dan sebagian orang tua sudah memberi izin berdasarkan rencana lama. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Melanjutkan kegiatan dengan tambahan pendamping karena izin dan biaya sudah dipersiapkan, lalu menyesuaikan aktivitas jika cuaca memburuk di lokasi.","Membatalkan seluruh kegiatan luar kelas untuk semester ini karena perubahan cuaca menunjukkan risiko yang tidak dapat dikendalikan sekolah secara penuh.","Menetapkan ambang lanjut atau batal berdasarkan keselamatan, memperbarui informasi dan persetujuan, serta menyediakan alternatif belajar yang layak bila ambang risiko terlampaui.","Meminta penyedia menentukan kelayakan kegiatan karena mereka lebih mengenal lokasi dan dapat mempertimbangkan dampak biaya pembatalan pada semua peserta."]],[147,"KEWIRAUSAHAAN","Guru mempunyai gagasan pojok belajar mandiri menggunakan bahan bekas. Sekolah belum pernah mencobanya. Tindakan awal yang paling tepat adalah:",["Membuat pojok belajar di semua kelas agar penggunaan bahan bekas segera meluas.","Menilai keberhasilan pojok terutama dari banyaknya bahan bekas yang terkumpul.","Memulai uji kecil dengan tujuan dan indikator penggunaan yang jelas.","Membuat pojok dahulu dan menyerahkan cara penggunaannya kepada siswa."]],[247,"KEWIRAUSAHAAN","Guru mempunyai gagasan pojok belajar mandiri menggunakan bahan bekas. Sekolah belum pernah mencobanya. Dalam perkembangan berikutnya, Pojok disukai siswa tertentu tetapi hampir tidak dipakai siswa yang tertinggal. Ruang terbatas dan guru ingin segera membuatnya di semua kelas. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Memperluas pojok belajar berdasarkan tingginya minat pengguna aktif karena semakin banyak lokasi akan memberi peluang siswa lain ikut menggunakannya.","Mengutamakan penggunaan oleh siswa yang tertinggal melalui jadwal wajib agar fasilitas baru langsung berkontribusi pada pengurangan kesenjangan belajar.","Memindahkan pojok ke perpustakaan agar ruang kelas tidak terbebani dan guru dapat menyerahkan pengelolaan inovasi kepada satu petugas khusus.","Mengamati hambatan penggunaan kelompok yang belum terlayani, menguji dukungan dan desain ulang, lalu memperluas hanya komponen yang menunjukkan manfaat inklusif."]],[148,"KEWIRAUSAHAAN","Sekolah ingin memanfaatkan alumni untuk membantu pengenalan berbagai pekerjaan kepada siswa. Tindakan awal yang paling tepat adalah:",["Mengundang alumni secara bergiliran tanpa membahas kaitan materi dengan usia siswa.","Memilih alumni dengan pekerjaan paling terkenal agar siswa lebih tertarik.","Mencocokkan pengalaman alumni dengan tujuan pembelajaran dan kebutuhan usia siswa.","Meminta semua alumni menceritakan perjalanan kerja dengan format yang sama."]],[248,"KEWIRAUSAHAAN","Sekolah ingin memanfaatkan alumni untuk membantu pengenalan berbagai pekerjaan kepada siswa. Dalam perkembangan berikutnya, Alumni dengan usaha besar meminta promosi produknya. Alumni lain mempunyai profesi yang relevan tetapi tidak dapat hadir langsung. Siswa mengira sukses hanya berarti kaya. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Menyusun pengalaman profesi yang beragam, menolak promosi yang menggeser tujuan, dan menggunakan pertemuan jarak jauh untuk membahas kontribusi serta proses belajar.","Mengutamakan alumni pengusaha besar karena keberhasilan finansialnya mudah dipahami dan dapat memberi motivasi kuat bagi siswa untuk memiliki cita-cita.","Memilih hanya alumni yang dapat hadir langsung agar kegiatan lebih hidup dan siswa mempunyai kesempatan bertanya tanpa kendala komunikasi digital.","Meminta alumni berbicara tanpa panduan materi agar kisah pribadi mereka terasa autentik dan siswa dapat memilih sendiri arti sukses yang disukai."]],[149,"KEWIRAUSAHAAN","Guru ingin menggunakan AI untuk membantu menyiapkan latihan siswa. Kepala sekolah perlu memberi arahan awal. Tindakan awal yang paling tepat adalah:",["Menggunakan soal AI langsung agar guru dapat menghemat waktu persiapan.","Memastikan soal ditinjau guru dan penggunaannya sesuai tujuan serta kebutuhan siswa.","Meminta AI meninjau kembali soalnya sendiri tanpa pemeriksaan oleh guru.","Mengizinkan AI hanya untuk soal mudah tanpa memeriksa kesesuaiannya dengan tujuan belajar."]],[249,"KEWIRAUSAHAAN","Guru ingin menggunakan AI untuk membantu menyiapkan latihan siswa. Kepala sekolah perlu memberi arahan awal. Dalam perkembangan berikutnya, AI menghasilkan soal cepat, tetapi beberapa jawaban salah dan materi memuat data siswa. Guru ingin langsung memakai soal untuk asesmen penting minggu depan. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Menggunakan keluaran AI sebagai latihan lebih dahulu tanpa pemeriksaan menyeluruh agar kesalahan dapat ditemukan dari respons siswa sebelum asesmen penting.","Membatasi data yang dimasukkan, mewajibkan pemeriksaan isi dan kunci oleh guru, serta menguji kelayakan sebelum memakai hasil AI untuk keputusan asesmen.","Meminta dua aplikasi AI membandingkan jawaban sehingga guru dapat langsung memakai soal yang kuncinya disepakati kedua sistem secara otomatis.","Menghentikan semua penggunaan AI karena adanya kesalahan menunjukkan alat tersebut belum mampu mendukung kegiatan pembelajaran yang dapat dipercaya."]],[150,"KEWIRAUSAHAAN","Mitra menawarkan perangkat gratis untuk mendukung kegiatan belajar. Kepala sekolah ingin menilai kelayakannya. Tindakan awal yang paling tepat adalah:",["Memeriksa manfaat, syarat bantuan, dan kemampuan sekolah merawat perangkat.","Menerima semua perangkat karena sekolah tidak perlu membayar pembeliannya.","Menilai tawaran dari jumlah perangkat tanpa memeriksa syarat dan perawatannya.","Meminta mitra menyerahkan perangkat lebih dahulu lalu menilai kegunaannya."]],[250,"KEWIRAUSAHAAN","Mitra menawarkan perangkat gratis untuk mendukung kegiatan belajar. Kepala sekolah ingin menilai kelayakannya. Dalam perkembangan berikutnya, Perangkat gratis hanya bekerja dengan langganan berbayar setelah enam bulan. Data siswa disimpan penyedia dan sekolah belum memiliki petugas teknis. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Menerima perangkat untuk enam bulan pertama agar siswa segera mendapat manfaat, kemudian mencari sumber dana langganan jika penggunaannya terbukti menarik.","Menerima perangkat tetapi membatasi akses pada siswa tertentu agar biaya dan kebutuhan dukungan teknis lebih ringan setelah masa gratis berakhir.","Menghitung biaya berkelanjutan, memastikan perlindungan dan pengambilan kembali data, serta memilih menerima atau menolak berdasarkan kesiapan dan alternatif layanan.","Menolak bantuan yang melibatkan langganan agar sekolah tidak memiliki kewajiban jangka panjang meskipun ada kemungkinan negosiasi biaya dan tata kelola data."]],[151,"KEWIRAUSAHAAN","Kegiatan pameran karya siswa berlangsung ramai tetapi sedikit siswa bisa menjelaskan proses membuat karyanya. Tindakan awal yang paling tepat adalah:",["Meninjau apakah kegiatan membangun pemahaman siswa selain menghasilkan tampilan karya.","Menambah latihan presentasi tanpa memeriksa keterlibatan siswa dalam proses berkarya.","Menilai pameran berhasil karena banyak pengunjung hadir melihat karya siswa.","Meminta guru menjelaskan proses pembuatan agar pertanyaan pengunjung terjawab."]],[251,"KEWIRAUSAHAAN","Kegiatan pameran karya siswa berlangsung ramai tetapi sedikit siswa bisa menjelaskan proses membuat karyanya. Dalam perkembangan berikutnya, Orang tua membantu sebagian besar produk. Sponsor menyukai kemeriahan dan menawarkan pendanaan tahun depan hanya jika jumlah pengunjung meningkat. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Mempertahankan dukungan orang tua karena mutu produk menarik pengunjung, lalu menambah latihan presentasi agar siswa lebih siap menjawab pertanyaan.","Menghapus dukungan sponsor agar seluruh karya dapat dibuat mandiri tanpa tuntutan jumlah pengunjung yang memengaruhi tujuan pendidikan sekolah.","Mewajibkan setiap siswa menghafal penjelasan karyanya sehingga pameran berikutnya tetap ramai sekaligus memenuhi harapan kemampuan presentasi siswa.","Mendesain bukti proses dan penjelasan siswa sebagai ukuran utama, membatasi bantuan yang menggantikan kerja siswa, serta menegosiasikan ukuran keberhasilan dengan sponsor."]],[152,"KEWIRAUSAHAAN","Sekolah ingin mengembangkan kegiatan keterampilan yang sesuai potensi lingkungan sekitar. Tindakan awal yang paling tepat adalah:",["Memilih keterampilan yang paling populer tanpa memetakan potensi lingkungan.","Meminta warga menentukan kegiatan tanpa membahas pengalaman belajar siswa.","Memetakan potensi lokal dan menghubungkannya dengan pengalaman belajar yang bermakna.","Mencontoh kegiatan sekolah lain sebelum menilai kesesuaiannya dengan potensi lokal."]],[252,"KEWIRAUSAHAAN","Sekolah ingin mengembangkan kegiatan keterampilan yang sesuai potensi lingkungan sekitar. Dalam perkembangan berikutnya, Potensi usaha lokal memberi keuntungan tetapi menggunakan proses yang menghasilkan limbah. Mitra ingin siswa meniru prosesnya, sedangkan guru mengusulkan pendekatan ramah lingkungan. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Mengikuti proses mitra terlebih dahulu agar siswa memahami usaha yang nyata, kemudian membahas dampak lingkungan sebagai materi terpisah di kelas.","Menjadikan persoalan lingkungan sebagai tantangan desain, menguji alternatif proses bersama mitra, dan menilai nilai pendidikan serta kelayakan tanpa menormalisasi dampak buruk.","Menghindari seluruh potensi usaha tersebut dan memilih keterampilan lain agar siswa tidak terpapar praktik yang berpotensi merusak lingkungan.","Menggunakan pendekatan ramah lingkungan guru tanpa melibatkan mitra lagi karena tujuan pendidikan dapat ditentukan sekolah meskipun kelayakan usaha belum teruji."]],[153,"KEWIRAUSAHAAN","Guru ingin mencoba waktu khusus bagi siswa untuk mengajukan pertanyaan sendiri tentang materi pelajaran. Tindakan awal yang paling tepat adalah:",["Menetapkan jumlah pertanyaan yang wajib diajukan setiap siswa sebagai ukuran utama.","Menyiapkan uji coba dan mengamati kualitas pertanyaan serta keterlibatan siswa.","Memberi waktu bertanya tanpa mengamati jenis pertanyaan dan keterlibatan siswa.","Meminta guru menyiapkan semua pertanyaan agar pembahasan mudah dikendalikan."]],[253,"KEWIRAUSAHAAN","Guru ingin mencoba waktu khusus bagi siswa untuk mengajukan pertanyaan sendiri tentang materi pelajaran. Dalam perkembangan berikutnya, Jumlah pertanyaan bertambah tetapi berasal dari siswa yang sama. Guru khawatir target materi tidak selesai, sementara siswa lain merasa takut salah. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Mempertahankan format karena pertumbuhan jumlah pertanyaan menunjukkan budaya berpikir mulai berkembang dan siswa lain akan menyesuaikan diri secara bertahap.","Menguji saluran pertanyaan yang aman dan waktu terarah, memantau partisipasi kelompok berbeda, serta mengaitkan pertanyaan dengan pemahaman konsep yang dituju.","Membatasi pertanyaan pada siswa yang belum berbicara agar pemerataan partisipasi tercapai meskipun pertanyaan siswa aktif tidak seluruhnya dibahas.","Memindahkan semua pertanyaan ke tugas rumah agar target materi tetap selesai dan siswa memiliki waktu lebih lama untuk menyiapkan pertanyaan terbaik."]],[154,"KEWIRAUSAHAAN","Sekolah akan membuat formulir daring untuk mempermudah komunikasi dengan orang tua. Tindakan awal yang paling tepat adalah:",["Memasukkan sebanyak mungkin pertanyaan agar sekolah memperoleh informasi lengkap.","Merancang formulir berdasarkan informasi yang diperlukan dan kemudahan akses keluarga.","Mewajibkan seluruh komunikasi melalui formulir sebelum menilai akses keluarga.","Memilih tampilan formulir terlebih dahulu sebelum menentukan informasi yang diperlukan."]],[254,"KEWIRAUSAHAAN","Sekolah akan membuat formulir daring untuk mempermudah komunikasi dengan orang tua. Dalam perkembangan berikutnya, Formulir mengurangi pekerjaan staf, tetapi keluarga tanpa internet jarang merespons. Tim menyarankan kewajiban mengisi daring agar data terkumpul dalam satu format. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Mewajibkan pengisian daring dengan tenggat lebih panjang bagi keluarga tanpa internet agar seluruh data tetap masuk melalui satu saluran resmi.","Mengembalikan semua komunikasi ke formulir kertas agar tidak ada keluarga yang perlu bantuan khusus dan sekolah mempunyai prosedur yang sama.","Meminta perwakilan orang tua mengumpulkan jawaban keluarga lain menggunakan akun pribadinya agar staf sekolah tidak perlu mengelola dua jalur layanan.","Menyediakan jalur setara bagi keluarga tanpa internet, menyatukan input melalui bantuan petugas, dan memantau apakah kemudahan administrasi juga memperbaiki akses layanan."]],[155,"KEWIRAUSAHAAN","Sekolah merencanakan program baru dengan dana sumbangan yang belum pasti jumlahnya. Tindakan awal yang paling tepat adalah:",["Menetapkan program penuh berdasarkan jumlah sumbangan yang diharapkan.","Menunda seluruh perencanaan sampai semua sumbangan terkumpul.","Menetapkan rancangan sesuai sumber daya terkonfirmasi dan menyiapkan alternatif bila dana tidak mencukupi.","Menyusun anggaran dari kebutuhan program tanpa menyiapkan pilihan bila dana kurang."]],[255,"KEWIRAUSAHAAN","Sekolah merencanakan program baru dengan dana sumbangan yang belum pasti jumlahnya. Dalam perkembangan berikutnya, Sumbangan sudah dijanjikan secara lisan, tetapi pencairan bergantung pada hasil usaha mitra. Vendor meminta uang muka dan program menyasar siswa yang sangat membutuhkan. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Membayar uang muka dari dana kegiatan lain karena kebutuhan siswa mendesak dan janji mitra memberikan dasar kepercayaan yang cukup untuk memulai.","Menunda seluruh program sampai sumbangan diterima agar sekolah tidak menanggung risiko pembiayaan meskipun dukungan minimal dapat dilaksanakan dengan dana tersedia.","Meminta keluarga peserta menutup sementara kekurangan dengan janji pengembalian agar program berjalan tepat waktu dan sekolah tidak mengalihkan anggaran lain.","Membagi pelaksanaan dalam tahap yang dapat dibiayai, menghindari komitmen melebihi dana pasti, dan menyiapkan dukungan minimal bagi siswa prioritas sambil memverifikasi janji."]],[156,"KEWIRAUSAHAAN","Sekolah mencoba layanan konsultasi belajar baru tetapi hanya sedikit siswa datang. Tindakan awal yang paling tepat adalah:",["Menutup layanan karena sedikitnya pengunjung menunjukkan program tidak dibutuhkan.","Menambah jadwal konsultasi tanpa mencari kendala yang dialami siswa.","Menggali alasan rendahnya penggunaan sebelum menilai keberhasilan layanan.","Mengukur keberhasilan hanya dari jumlah siswa yang datang pada masa uji coba."]],[256,"KEWIRAUSAHAAN","Sekolah mencoba layanan konsultasi belajar baru tetapi hanya sedikit siswa datang. Dalam perkembangan berikutnya, Survei menunjukkan siswa takut dianggap lemah jika datang. Jadwal berbenturan dengan angkutan pulang, tetapi tim menganggap kurangnya sosialisasi sebagai penyebab utama. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Meningkatkan sosialisasi tentang manfaat konsultasi karena siswa perlu memahami bahwa dukungan sekolah bertujuan membantu dan tidak menilai kelemahannya.","Menguji akses waktu yang realistis dan komunikasi tanpa stigma, mengamati siapa yang menggunakan layanan, serta membandingkan hambatan sebelum menambah promosi umum.","Mewajibkan siswa dengan nilai rendah mengikuti konsultasi agar layanan segera menjangkau kelompok yang paling membutuhkan walaupun jadwal belum disesuaikan.","Memindahkan konsultasi ke saluran daring agar masalah transportasi selesai dan siswa bisa menggunakan layanan tanpa terlihat oleh teman sekelas."]],[157,"SUPERVISI","Dalam observasi, guru memberi kesempatan menjawab hanya kepada beberapa siswa. Kepala sekolah akan memberi umpan balik. Tindakan awal yang paling tepat adalah:",["Meminta guru memberi giliran sama banyak tanpa membahas bukti hasil observasi.","Menggunakan bukti distribusi kesempatan menjawab untuk mendiskusikan perbaikan partisipasi.","Menilai guru kurang adil lalu meminta perubahan sebelum mendiskusikan situasinya.","Meminta siswa yang jarang menjawab lebih aktif tanpa membahas kesempatan yang diberikan."]],[257,"SUPERVISI","Dalam observasi, guru memberi kesempatan menjawab hanya kepada beberapa siswa. Kepala sekolah akan memberi umpan balik. Dalam perkembangan berikutnya, Siswa yang menjawab memperoleh nilai tinggi, sedangkan lainnya diam tetapi menyelesaikan tugas. Guru menganggap diam berarti paham dan waktu observasi hanya satu pertemuan. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Menguji pemahaman siswa yang diam melalui bukti tambahan, mendiskusikan strategi pemerataan respons, dan mengamati kembali pengaruhnya tanpa menyimpulkan dari satu gejala.","Meminta guru menunjuk seluruh siswa secara bergiliran agar setiap anak memperoleh kesempatan yang sama dan perilaku diam tidak lagi sulit ditafsirkan.","Menilai partisipasi sudah memadai karena semua siswa menyelesaikan tugas, lalu menyarankan variasi bertanya sebagai pengembangan tambahan pada pertemuan berikutnya.","Menunda semua umpan balik sampai nilai akhir tersedia karena kualitas jawaban dan pekerjaan satu pertemuan belum cukup menunjukkan pemahaman siswa."]],[158,"SUPERVISI","Seorang guru menganggap supervisi hanya memeriksa kelengkapan dokumen pembelajaran. Tindakan awal yang paling tepat adalah:",["Menjelaskan supervisi sebagai pemeriksaan dokumen yang dilakukan secara berkala.","Menyarankan guru melengkapi dokumen dahulu sebelum membahas praktik pembelajaran.","Menjelaskan bahwa supervisi membantu perbaikan praktik dan pengalaman belajar siswa.","Menyatakan supervisi untuk menilai kinerja tanpa menjelaskan proses perbaikannya."]],[258,"SUPERVISI","Seorang guru menganggap supervisi hanya memeriksa kelengkapan dokumen pembelajaran. Dalam perkembangan berikutnya, Guru mempunyai dokumen lengkap tetapi mengeluh observasi menambah tekanan. Data siswa menunjukkan kebutuhan dukungan yang tidak terlihat dalam rencana pembelajaran. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Menyepakati fokus observasi pada kebutuhan siswa, menggunakan dokumen sebagai konteks, dan membangun umpan balik yang menghasilkan satu perbaikan praktik terukur.","Memulai dari penilaian dokumen yang sudah lengkap agar guru merasa dihargai, kemudian menambahkan observasi bila ia menyatakan siap menghadapi prosesnya.","Mengurangi observasi dan meminta guru melaporkan perubahan praktik melalui refleksi tertulis agar tujuan pembinaan tercapai tanpa menambah tekanan di kelas.","Mengutamakan capaian hasil siswa sebagai dasar nilai supervisi agar proses objektif dan tidak bergantung pada kenyamanan guru saat pembelajaran diamati."]],[159,"SUPERVISI","Setelah observasi, kepala sekolah dan guru menyepakati penggunaan pertanyaan terbuka. Belum ada rencana pemantauan. Tindakan awal yang paling tepat adalah:",["Meminta guru menggunakan pertanyaan terbuka lalu menunggu laporan pada akhir semester.","Menjadwalkan pertemuan berikutnya tanpa menyepakati bukti yang akan dibahas.","Meminta guru mencatat jumlah pertanyaan tanpa melihat perubahan respons siswa.","Menentukan waktu uji coba dan bukti perubahan untuk dibahas pada pertemuan berikutnya."]],[259,"SUPERVISI","Setelah observasi, kepala sekolah dan guru menyepakati penggunaan pertanyaan terbuka. Belum ada rencana pemantauan. Dalam perkembangan berikutnya, Guru sudah mengubah pertanyaan, tetapi respons siswa masih pendek. Ia menyimpulkan strategi tidak cocok dan meminta mengganti fokus sebelum pertemuan monitoring. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Mengganti strategi sesuai pilihan guru agar kepemilikan perbaikan tetap tinggi dan proses supervisi tidak terasa memaksakan rekomendasi pimpinan.","Meminta guru mempertahankan strategi tanpa perubahan satu semester lagi karena perubahan kemampuan menjawab membutuhkan waktu yang tidak singkat.","Memeriksa waktu tunggu, tindak lanjut respons, dan dukungan siswa, lalu menguji penyesuaian satu komponen sebelum menyimpulkan efektivitas strategi.","Meningkatkan jumlah pertanyaan terbuka pada setiap pertemuan agar siswa memperoleh lebih banyak latihan sebelum hasil strategi dievaluasi kembali."]],[160,"SUPERVISI","Hasil asesmen awal menunjukkan kemampuan siswa berbeda. Guru memakai tugas yang sama dengan dukungan yang sama untuk semua. Tindakan awal yang paling tepat adalah:",["Membahas penyesuaian dukungan dan tantangan berdasarkan kebutuhan belajar siswa.","Meminta semua siswa mengerjakan tugas lebih lama dengan dukungan tetap sama.","Mengelompokkan siswa menurut kemampuan tanpa mengubah dukungan dan tantangan.","Mengurangi kesulitan tugas untuk seluruh siswa agar semuanya dapat menyelesaikan."]],[260,"SUPERVISI","Hasil asesmen awal menunjukkan kemampuan siswa berbeda. Guru memakai tugas yang sama dengan dukungan yang sama untuk semua. Dalam perkembangan berikutnya, Guru takut penyesuaian dianggap tidak adil. Siswa cepat selesai merasa bosan, sedangkan siswa lain memerlukan panduan lebih banyak. Waktu persiapan guru terbatas. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Meminta semua siswa menyelesaikan tugas paling sederhana lebih dahulu agar dasar kemampuan sama sebelum guru menambahkan tantangan pada pertemuan berikutnya.","Mengelompokkan siswa secara tetap berdasarkan hasil asesmen awal supaya guru dapat menyiapkan tiga tingkat tugas dan menghemat waktu persiapan mingguan.","Memberikan tugas tambahan hanya kepada siswa cepat selesai agar kelas tetap menggunakan materi yang sama dan guru tidak perlu membuat dukungan berbeda.","Menyepakati tujuan inti yang sama, menyediakan variasi dukungan dan pengayaan yang sederhana, serta memeriksa kemajuan tiap kelompok tanpa menetapkan label kemampuan permanen."]],[161,"SUPERVISI","Siswa tampak antusias bermain dalam kegiatan belajar, tetapi tujuan konsep tidak dibahas kembali. Tindakan awal yang paling tepat adalah:",["Menilai keberhasilan kegiatan dari antusiasme siswa selama permainan.","Meminta guru menambah penjelasan konsep tanpa memeriksa pemahaman siswa.","Memeriksa hubungan kegiatan dengan pemahaman konsep melalui bukti respons siswa.","Mengurangi waktu bermain tanpa melihat hubungan kegiatan dengan konsep belajar."]],[261,"SUPERVISI","Siswa tampak antusias bermain dalam kegiatan belajar, tetapi tujuan konsep tidak dibahas kembali. Dalam perkembangan berikutnya, Guru menunjukkan hasil survei kepuasan yang tinggi, tetapi siswa gagal menjelaskan konsep setelah permainan. Guru khawatir evaluasi konsep akan mengurangi kesenangan belajar. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Mengurangi permainan dan menambah penjelasan langsung karena hasil survei kepuasan tidak cukup membuktikan kegiatan mendukung pemahaman konsep siswa.","Melanjutkan permainan sebagai pembuka lalu memberi tes pada akhir minggu agar guru tetap menjaga kesenangan sambil memperoleh data hasil konsep.","Mempertahankan unsur keterlibatan yang membantu, menambah jembatan refleksi menuju konsep, dan menguji pemahaman sebelum menilai permainan berhasil atau gagal.","Menggunakan keaktifan dan kerja sama sebagai indikator utama karena permainan mempunyai manfaat lain yang tidak sepenuhnya diukur melalui pertanyaan konsep."]],[162,"SUPERVISI","Guru menilai hasil pekerjaan siswa hanya dengan angka tanpa penjelasan bagian yang perlu diperbaiki. Tindakan awal yang paling tepat adalah:",["Meminta guru memberikan angka yang lebih rinci agar siswa mengetahui perbedaannya.","Menambahkan komentar umum yang sama pada seluruh pekerjaan siswa.","Meminta siswa membandingkan nilainya dengan teman untuk menentukan perbaikan.","Membahas pemberian umpan balik spesifik yang membantu siswa menentukan langkah belajar berikutnya."]],[262,"SUPERVISI","Guru menilai hasil pekerjaan siswa hanya dengan angka tanpa penjelasan bagian yang perlu diperbaiki. Dalam perkembangan berikutnya, Guru mengajar banyak siswa dan merasa komentar individual tidak realistis. Kesalahan siswa beragam, tetapi beberapa pola muncul pada banyak pekerjaan. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Mengelompokkan pola kesalahan untuk umpan balik kelas yang terarah, menambah tindak lanjut individual bagi kebutuhan khusus, dan memeriksa apakah siswa menggunakan masukan.","Meminta guru memberi komentar lengkap pada setiap pekerjaan karena umpan balik hanya bermakna bila setiap siswa menerima informasi yang sepenuhnya individual.","Menyediakan kunci jawaban bagi seluruh siswa agar mereka dapat menemukan kesalahannya sendiri tanpa menambah beban koreksi guru secara berlebihan.","Menggunakan komentar umum yang sama bagi pekerjaan dengan nilai rendah agar semua siswa memperoleh pesan perbaikan dan proses koreksi tetap efisien."]],[163,"SUPERVISI","Guru sudah mengikuti pelatihan asesmen tetapi belum menerapkan perubahan di kelas. Tindakan awal yang paling tepat adalah:",["Mengirim guru mengikuti pelatihan asesmen lagi tanpa membahas kendala penerapan.","Mendiskusikan hambatan penerapan dan menyepakati uji praktik yang terjangkau.","Menetapkan penerapan seluruh materi pelatihan sekaligus pada minggu berikutnya.","Meminta guru membuat laporan pelatihan tanpa mendiskusikan praktik di kelas."]],[263,"SUPERVISI","Guru sudah mengikuti pelatihan asesmen tetapi belum menerapkan perubahan di kelas. Dalam perkembangan berikutnya, Guru memahami teknik pelatihan, tetapi jadwal padat dan format administrasi lama menyita waktu. Kepala sekolah juga meminta banyak bukti tertulis untuk monitoring. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Meminta guru melengkapi format administrasi baru terlebih dahulu agar pelaksanaan asesmen memiliki dasar tertulis yang mudah diperiksa dalam supervisi.","Mengirim guru mengikuti pelatihan lanjutan agar ia memperoleh strategi pengelolaan waktu yang diperlukan untuk menerapkan teknik asesmen sebelumnya.","Membebaskan guru menentukan waktu penerapan tanpa tenggat karena perubahan praktik membutuhkan kesiapan pribadi yang tidak dapat dipaksakan melalui monitoring.","Mengurangi tuntutan bukti yang tidak relevan, memilih satu praktik asesmen formatif untuk diuji, dan memakai bukti pekerjaan siswa sebagai dasar monitoring perubahan."]],[164,"SUPERVISI","Seorang siswa sulit membaca instruksi tugas, tetapi bisa menjelaskan gagasan secara lisan. Tindakan awal yang paling tepat adalah:",["Membahas dukungan akses instruksi dan cara memperoleh bukti pemahaman siswa secara sesuai.","Menilai siswa hanya dari penjelasan lisan tanpa membahas akses instruksi tugas.","Meminta siswa membaca instruksi berulang kali sebelum memperoleh bantuan.","Mengurangi isi tugas tanpa memeriksa pemahaman dan hambatan membaca instruksi."]],[264,"SUPERVISI","Seorang siswa sulit membaca instruksi tugas, tetapi bisa menjelaskan gagasan secara lisan. Dalam perkembangan berikutnya, Asesmen bertujuan mengukur penalaran sains, tetapi semua jawaban wajib tertulis panjang. Guru takut perubahan format mengurangi standar dan siswa lain menganggapnya kemudahan khusus. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Tetap menggunakan jawaban tertulis tetapi menambah waktu agar standar format terjaga dan siswa mempunyai kesempatan lebih banyak menunjukkan penalarannya.","Mengurangi tingkat kesulitan konsep untuk siswa tersebut agar hambatan membaca tidak membuatnya gagal dan ia tetap mempunyai pengalaman keberhasilan.","Mengubah semua asesmen menjadi lisan agar tidak ada siswa yang merasa diberi perlakuan berbeda dan guru memakai satu format yang sama.","Memisahkan penalaran yang diukur dari hambatan membaca, menyediakan akses serta format respons setara, dan menjaga rubrik konsep yang sama dengan penjelasan keadilan dukungan."]],[165,"SUPERVISI","Kepala sekolah akan menentukan fokus supervisi semester. Data menunjukkan siswa kesulitan menjelaskan alasan jawaban. Tindakan awal yang paling tepat adalah:",["Memilih fokus kelengkapan rencana pembelajaran tanpa mengaitkan kesulitan penalaran.","Memilih fokus praktik yang membantu guru mengembangkan penalaran dan penjelasan siswa.","Memusatkan supervisi pada kecepatan siswa menjawab pertanyaan guru.","Meminta guru menambah jumlah soal tanpa meninjau cara siswa menjelaskan jawaban."]],[265,"SUPERVISI","Kepala sekolah akan menentukan fokus supervisi semester. Data menunjukkan siswa kesulitan menjelaskan alasan jawaban. Dalam perkembangan berikutnya, Sebagian guru sudah baik pada penalaran tetapi bermasalah pada pengelolaan kelas. Tim meminta satu fokus seragam agar formulir supervisi mudah dibuat. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Menetapkan fokus umum penalaran dengan fokus individual berdasarkan bukti kebutuhan, menggunakan instrumen ringkas yang memungkinkan variasi tanpa kehilangan keterbandingan proses.","Memakai satu fokus penalaran pada semua guru karena data sekolah menunjukkan masalah bersama dan instrumen seragam memudahkan akuntabilitas pelaksanaan.","Memberi setiap guru kebebasan memilih fokus sendiri agar supervisi sesuai kebutuhan dan tidak terasa ditentukan berdasarkan angka rata-rata sekolah.","Mendahulukan pengelolaan kelas bagi semua guru karena kondisi kelas yang tertib merupakan prasyarat sebelum penalaran siswa dapat dikembangkan."]],[166,"SUPERVISI","Observasi menunjukkan guru hampir selalu menjelaskan, sementara siswa hanya menyalin. Kepala sekolah ingin membuka diskusi perbaikan. Tindakan awal yang paling tepat adalah:",["Meminta guru mengurangi waktu penjelasan tanpa membahas aktivitas berpikir siswa.","Menilai pembelajaran dari lengkapnya catatan yang disalin siswa.","Mendiskusikan kesempatan siswa berpikir dan menunjukkan pemahaman selama pembelajaran.","Menyarankan siswa mencatat lebih ringkas tanpa mengubah kesempatan menunjukkan pemahaman."]],[266,"SUPERVISI","Observasi menunjukkan guru hampir selalu menjelaskan, sementara siswa hanya menyalin. Kepala sekolah ingin membuka diskusi perbaikan. Dalam perkembangan berikutnya, Guru menyatakan penjelasan diperlukan karena konsep sulit. Sebagian siswa membutuhkan contoh terstruktur, sebagian lainnya mampu menyelesaikan masalah sendiri. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Menyepakati perpaduan penjelasan singkat, latihan dengan dukungan bertahap, dan respons siswa yang memungkinkan guru menyesuaikan bantuan berdasarkan bukti pemahaman.","Mengurangi penjelasan guru secara tajam dan menambah diskusi kelompok agar siswa mempunyai waktu lebih luas membangun sendiri pemahaman konsep.","Mempertahankan penjelasan sampai semua siswa menguasai konsep dasar lalu memberikan pemecahan masalah kepada kelompok yang sudah siap pada akhir pelajaran.","Menambahkan pertanyaan di sela penjelasan tanpa mengubah alur materi agar keterlibatan meningkat dan kebutuhan contoh terstruktur tetap terpenuhi."]],[167,"SUPERVISI","Guru merasa pembelajarannya berhasil karena kelas tenang. Kepala sekolah belum melihat bukti pemahaman siswa. Tindakan awal yang paling tepat adalah:",["Meminta bukti respons atau pekerjaan siswa untuk menilai pemahaman selain ketenangan kelas.","Menggunakan ketenangan kelas sebagai indikator utama keberhasilan pembelajaran.","Menilai keberhasilan dari selesainya penjelasan materi oleh guru.","Meminta siswa menyatakan senang belajar tanpa memeriksa bukti pemahaman mereka."]],[267,"SUPERVISI","Guru merasa pembelajarannya berhasil karena kelas tenang. Kepala sekolah belum melihat bukti pemahaman siswa. Dalam perkembangan berikutnya, Pekerjaan siswa banyak benar, tetapi polanya identik dengan contoh guru. Ketika konteks diubah, sebagian besar siswa tidak dapat memilih strategi penyelesaian. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Menambah variasi contoh yang dikerjakan guru agar siswa memiliki lebih banyak pola penyelesaian untuk dipakai ketika konteks soal berubah.","Membedakan ketepatan meniru dan kemampuan transfer, menguji respons pada konteks baru, lalu membahas dukungan yang membantu siswa menjelaskan pilihan strateginya.","Memberi lebih banyak latihan sejenis sebelum konteks diubah karena kegagalan transfer menunjukkan penguasaan prosedur dasar siswa belum cukup kuat.","Menilai pembelajaran efektif untuk tujuan prosedural dan menyerahkan kemampuan transfer pada unit berikutnya agar evaluasi sesuai materi yang sudah diajarkan."]],[168,"SUPERVISI","Guru meminta contoh praktik dari rekan yang lebih berpengalaman setelah menerima umpan balik supervisi. Tindakan awal yang paling tepat adalah:",["Mengatur belajar antarguru dengan fokus dan refleksi penerapan yang jelas.","Meminta guru meniru seluruh cara mengajar rekan yang lebih berpengalaman.","Menjadwalkan observasi rekan tanpa menentukan fokus dan pembahasan penerapan.","Memberikan contoh bahan ajar rekan tanpa membahas penggunaannya di kelas guru tersebut."]],[268,"SUPERVISI","Guru meminta contoh praktik dari rekan yang lebih berpengalaman setelah menerima umpan balik supervisi. Dalam perkembangan berikutnya, Praktik rekan berhasil pada kelas kecil, sedangkan kelas guru tersebut besar dan sarana terbatas. Guru ingin menyalin seluruh langkah agar hasilnya cepat sama. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Meminta guru mengikuti langkah rekan secara utuh selama uji pertama agar perbedaan hasil dapat dikaitkan dengan konteks, bukan perubahan rancangan.","Mengidentifikasi prinsip yang membuat praktik berhasil, menyesuaikan langkah dengan kondisi kelas, dan menguji satu perubahan melalui bukti sebelum memperluas penerapan.","Mencari contoh dari sekolah dengan ukuran kelas yang sama agar guru tidak perlu mengubah praktik yang sudah terbukti berhasil pada kondisi tertentu.","Menyerahkan seluruh adaptasi kepada guru setelah observasi rekan agar ia memiliki otonomi profesional tanpa tuntutan bukti tambahan dari kepala sekolah."]],[169,"SUPERVISI","Guru memberi tugas tambahan yang lebih banyak kepada siswa yang cepat menyelesaikan latihan. Tindakan awal yang paling tepat adalah:",["Membahas pengayaan yang menambah kedalaman berpikir daripada hanya menambah jumlah pekerjaan.","Menambah jumlah soal sejenis agar siswa cepat tetap sibuk sampai kelas selesai.","Meminta siswa mengulang latihan yang sama untuk meningkatkan kecepatannya.","Meminta siswa menunggu teman selesai agar tugas semua siswa tetap seragam."]],[269,"SUPERVISI","Guru memberi tugas tambahan yang lebih banyak kepada siswa yang cepat menyelesaikan latihan. Dalam perkembangan berikutnya, Siswa cepat merasa dihukum karena selesai lebih dahulu. Guru belum memiliki bank pengayaan, dan siswa lain masih membutuhkan pendampingan pada tujuan dasar. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Mengurangi jumlah tugas tambahan tetapi mempertahankan jenis soal yang sama agar guru dapat menjaga kesetaraan materi tanpa menambah persiapan.","Meminta siswa cepat menjadi tutor teman sepanjang waktu tersisa sehingga mereka mempunyai peran bermanfaat dan guru dapat membantu kelompok lain.","Mengizinkan siswa cepat memilih kegiatan bebas yang mereka sukai agar penghargaan terhadap kecepatan kerja memulihkan motivasi tanpa memerlukan bank pengayaan.","Merancang satu tantangan terbuka yang memperdalam tujuan inti, memberi pilihan cara respons, dan mengatur kemandirian agar dukungan untuk siswa lain tetap berjalan."]],[170,"SUPERVISI","Sekolah ingin menilai keberhasilan pendampingan guru yang sudah berlangsung satu semester. Tindakan awal yang paling tepat adalah:",["Memeriksa perubahan praktik dan dampaknya pada pengalaman belajar siswa dengan bukti yang relevan.","Menggunakan jumlah pertemuan pendampingan sebagai ukuran utama keberhasilan.","Menilai keberhasilan dari kelengkapan laporan pendampingan selama semester.","Mengukur kepuasan guru saja tanpa memeriksa perubahan praktik dan pengalaman siswa."]],[270,"SUPERVISI","Sekolah ingin menilai keberhasilan pendampingan guru yang sudah berlangsung satu semester. Dalam perkembangan berikutnya, Dokumen tindak lanjut lengkap dan guru puas, tetapi data hasil siswa tidak menunjukkan perubahan rata-rata. Sebagian kelas membaik, sebagian memburuk, serta terdapat perubahan komposisi siswa. Kebijakan yang paling tepat dengan mempertimbangkan seluruh kondisi tersebut adalah:",["Menganalisis perubahan praktik dan hasil per kelompok dengan mempertimbangkan komposisi, memeriksa mekanisme pendampingan, dan memperbaiki fokus berdasarkan hubungan bukti yang dapat dipertanggungjawabkan.","Menggunakan kepuasan guru dan kelengkapan tindak lanjut sebagai ukuran utama karena rata-rata hasil siswa dipengaruhi banyak faktor di luar supervisi.","Menyimpulkan pendampingan belum berhasil berdasarkan rata-rata hasil sekolah, lalu mengganti seluruh strategi agar semester berikutnya memberi perubahan yang lebih jelas.","Mengambil praktik dari kelas yang membaik untuk diterapkan di semua kelas karena keberhasilan lokal merupakan bukti paling nyata yang tersedia bagi sekolah."]]]);
const HIGH_DISCRIMINATION=new Set([1,3,7,10,13,16,20,21,24,26,29,30,36,40,42,43,48,50,53,55,57,59,61,66,70]);
